window.__contenido("bigquery-paso-a-paso", {"bigquery-paso-a-paso-que-es-bigquery-y-la-consola":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 En palabras simples</div>\n\n<p>Con una base tradicional alquilas un local y lo amueblas: eliges el tamaño del servidor, lo prendes y lo mantienes. <strong>BigQuery es un servicio de mensajería</strong>: le das la consulta, Google pone las máquinas que hagan falta durante unos segundos y te cobra según el tamaño del paquete, es decir, los datos que leyó.</p>\n</div>\n\n\n<h2>Paso 1 — Qué lo hace distinto</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Característica</th>\n<th>Qué significa</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Sin servidores</strong></td>\n<td>No hay clústeres que crear ni apagar: escribes SQL y corre</td>\n</tr>\n<tr>\n<td><strong>Almacenamiento por columnas</strong></td>\n<td>Cada columna se guarda por separado: una consulta solo lee las columnas que nombra</td>\n</tr>\n<tr>\n<td><strong>Separación de almacenamiento y cómputo</strong></td>\n<td>Los datos se guardan una vez; el cómputo (<em>slots</em>) se asigna por consulta</td>\n</tr>\n<tr>\n<td><strong>Pago por uso (on-demand)</strong></td>\n<td>Se cobra por los <strong>bytes que procesa</strong> cada consulta, no por el tiempo ni por las filas devueltas</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 2 — La jerarquía</h2>\n<figure class=\"diagrama\" data-spec=\"{&quot;titulo&quot;:&quot;Proyecto → dataset → tablas y vistas&quot;,&quot;direccion&quot;:&quot;derecha&quot;,&quot;nodos&quot;:[{&quot;id&quot;:&quot;p&quot;,&quot;label&quot;:&quot;Proyecto de Google Cloud&quot;,&quot;icono&quot;:&quot;gcp&quot;,&quot;col&quot;:0,&quot;fila&quot;:0,&quot;color&quot;:&quot;gris&quot;,&quot;sub&quot;:&quot;tienda-andina-dev&quot;},{&quot;id&quot;:&quot;d&quot;,&quot;label&quot;:&quot;Dataset&quot;,&quot;icono&quot;:&quot;carpeta&quot;,&quot;col&quot;:1,&quot;fila&quot;:0,&quot;color&quot;:&quot;azul&quot;,&quot;sub&quot;:&quot;tienda, analitica… · región y permisos&quot;},{&quot;id&quot;:&quot;t&quot;,&quot;label&quot;:&quot;Tablas&quot;,&quot;icono&quot;:&quot;tabla&quot;,&quot;col&quot;:2,&quot;fila&quot;:0,&quot;color&quot;:&quot;naranja&quot;},{&quot;id&quot;:&quot;v&quot;,&quot;label&quot;:&quot;Vistas&quot;,&quot;icono&quot;:&quot;lupa&quot;,&quot;col&quot;:2,&quot;fila&quot;:1,&quot;color&quot;:&quot;verde&quot;}],&quot;grupos&quot;:[],&quot;flechas&quot;:[{&quot;de&quot;:&quot;p&quot;,&quot;a&quot;:&quot;d&quot;,&quot;label&quot;:&quot;&quot;,&quot;doble&quot;:false,&quot;sinpunta&quot;:false,&quot;explica&quot;:&quot;El proyecto factura las consultas. Adentro se crean datasets, cada uno con su región y sus permisos.&quot;},{&quot;de&quot;:&quot;d&quot;,&quot;a&quot;:&quot;t&quot;,&quot;label&quot;:&quot;&quot;,&quot;doble&quot;:false,&quot;sinpunta&quot;:false,&quot;explica&quot;:&quot;Las tablas guardan datos.&quot;},{&quot;de&quot;:&quot;d&quot;,&quot;a&quot;:&quot;v&quot;,&quot;label&quot;:&quot;&quot;,&quot;doble&quot;:false,&quot;sinpunta&quot;:false,&quot;explica&quot;:&quot;Las vistas guardan una consulta, que se ejecuta cada vez que las usas.&quot;}]}\"><figcaption>Proyecto → dataset → tablas y vistas</figcaption></figure>\n\n\n<p>El nombre completo de una tabla es <strong><code>proyecto.dataset.tabla</code></strong>, por ejemplo <code>`tienda-andina-dev.tienda.pedidos`</code> (con backticks porque el proyecto tiene guiones). El SQL de BigQuery se llama <strong>GoogleSQL</strong>.</p>\n<h2>Paso 3 — BigQuery Studio</h2>\n<p>Abre el <a href=\"#/bigquery\">BigQuery de práctica</a>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q01-studio.webp\" alt=\"La navegación de BigQuery (1), el explorador con el proyecto y sus datasets (2), el editor (3) y el validador que anticipa los bytes (4)\" loading=\"lazy\"><figcaption>La navegación de BigQuery (1), el explorador con el proyecto y sus datasets (2), el editor (3) y el validador que anticipa los bytes (4)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Zona</th>\n<th>Qué tiene</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Studio</strong></td>\n<td>Explorador, pestañas de consultas, editor y resultados: donde se trabaja</td>\n</tr>\n<tr>\n<td><strong>Pipelines and integration</strong></td>\n<td>Data transfers, Scheduled queries, Dataform</td>\n</tr>\n<tr>\n<td><strong>Governance</strong></td>\n<td>Sharing (Analytics Hub)</td>\n</tr>\n<tr>\n<td><strong>Administration</strong></td>\n<td>Jobs explorer, costos y Capacity management</td>\n</tr>\n</tbody></table></div>\n<p>El <strong>validador</strong> (arriba a la derecha del editor) hace un <em>dry run</em>: dice cuántos datos va a procesar la consulta <strong>antes</strong> de ejecutarla, sin costo. Es el hábito más importante de BigQuery.</p>\n<h2>Paso 4 — Qué es real en la práctica</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q01-no-simulado.webp\" alt=\"Overview - el proyecto, sus datasets y tablas, las consultas recientes y qué se puede practicar en cada sección\" loading=\"lazy\"><figcaption>Overview - el proyecto, sus datasets y tablas, las consultas recientes y qué se puede practicar en cada sección</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Real</th>\n<th>Simulado</th>\n</tr>\n</thead><tbody><tr>\n<td>GoogleSQL corre de verdad (sobre DuckDB en tu navegador)</td>\n<td>No hay proyecto de Google Cloud ni facturación</td>\n</tr>\n<tr>\n<td>La estimación de bytes por columnas y particiones, la caché y el historial de jobs</td>\n<td>Los precios son los de lista y los datos son chicos</td>\n</tr>\n<tr>\n<td>Particiones, clustering, cargas, MERGE, time travel, INFORMATION_SCHEMA</td>\n<td>Las transferencias leen los buckets de la práctica, no Google Ads ni YouTube</td>\n</tr>\n<tr>\n<td>Scheduled queries, Data transfers desde S3 y Cloud Storage, Dataform, Analytics Hub y reservas de slots</td>\n<td>Los horarios corren cuando abres la consola, como si hubieran corrido a su hora</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Pensar que se paga por tiempo o por filas devueltas.</strong> En el modelo on-demand se paga por los bytes que la consulta <em>lee</em>: una consulta que devuelve 5 filas puede leer toda la tabla.</li>\n<li><strong>Buscar el servidor.</strong> No hay máquinas que encender ni apagar; el dataset es un contenedor con región y permisos, no una base de datos en un servidor.</li>\n<li><strong>Ejecutar sin mirar el validador.</strong> La estimación de bytes aparece antes de correr la consulta: mirarla es gratis y evita sorpresas.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Sabes qué es BigQuery y qué lo hace distinto.</li>\n<li>Conoces la jerarquía proyecto → dataset → tabla.</li>\n<li>Ubicas cada zona de Studio.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-que-es-bigquery-y-la-consola-ej1","opciones":[{"text":"El tiempo que tarda la consulta","ok":false},{"text":"Los bytes que procesa cada consulta","ok":true},{"text":"Las filas que devuelve","ok":false},{"text":"Una tarifa fija por usuario","ok":false}],"enunciado":"<p>¿Qué cobra BigQuery en el modelo on-demand?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-que-es-bigquery-y-la-consola-ej2","opciones":[{"text":"Un contenedor de tablas y vistas con su región y sus permisos","ok":true},{"text":"Un servidor que hay que encender antes de consultar","ok":false},{"text":"Una carpeta de Cloud Storage con archivos CSV","ok":false},{"text":"Un grupo de usuarios con permisos sobre el proyecto","ok":false}],"enunciado":"<p>¿Qué es un dataset en BigQuery?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-que-es-bigquery-y-la-consola-ej3","opciones":[{"text":"Porque comprime las filas","ok":false},{"text":"Porque una consulta solo lee las columnas que nombra","ok":true},{"text":"Porque guarda las filas ordenadas por fecha","ok":false},{"text":"Porque cada columna se guarda en una región distinta","ok":false}],"enunciado":"<p>¿Por qué guardar por columnas abarata las consultas?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-que-es-bigquery-y-la-consola-ej4","opciones":[{"text":"En la factura","ok":false},{"text":"En el validador del editor (dry run)","ok":true},{"text":"En el Overview","ok":false},{"text":"En el historial de jobs, antes de ejecutar","ok":false}],"enunciado":"<p>¿Dónde ves cuántos datos va a leer una consulta antes de ejecutarla?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true}]},"bigquery-paso-a-paso-la-primera-consulta-y-los-bytes":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Un taxímetro que avisa antes</div>\n\n<p>BigQuery cobra como un taxímetro que marca lo que <strong>lee</strong>, no lo que te muestra. El validador te dice cuánto va a marcar antes de subir al taxi. Pedir <code>SELECT *</code> es pedirle al taxi que recorra todas las calles para traerte una sola dirección.</p>\n</div>\n\n\n<h2>Paso 1 — Una consulta nueva</h2>\n<p>En Studio, <strong>+</strong> (nueva pestaña) y ✎ para ponerle nombre:</p>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT canal, COUNT(*) AS pedidos\nFROM `tienda-andina-dev.tienda.pedidos`\nWHERE fecha_pedido &gt;= '2024-01-01'\nGROUP BY canal\nORDER BY pedidos DESC;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q02-editor.webp\" alt=\"La pestaña con su nombre (1), Run (2) y el validador - &quot;This query will process 63.66 KB when run&quot; (3)\" loading=\"lazy\"><figcaption>La pestaña con su nombre (1), Run (2) y el validador - &quot;This query will process 63.66 KB when run&quot; (3)</figcaption></figure>\n\n\n<h2>Paso 2 — Ejecutar</h2>\n<p><strong>Run</strong> o <strong>Ctrl+Enter</strong>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q02-resultado.webp\" alt=\"El resultado por canal (1) y la información del job (2) - bytes procesados, facturados, costo, duración y qué se leyó\" loading=\"lazy\"><figcaption>El resultado por canal (1) y la información del job (2) - bytes procesados, facturados, costo, duración y qué se leyó</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Dato del job</th>\n<th>Qué es</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Job ID</strong></td>\n<td>Cada consulta es un <em>job</em>, con su identificador</td>\n</tr>\n<tr>\n<td><strong>Bytes processed</strong></td>\n<td>Lo que se leyó: solo las columnas usadas y las particiones que pasan el filtro</td>\n</tr>\n<tr>\n<td><strong>Bytes billed</strong></td>\n<td>Lo que se cobra: se redondea y tiene un <strong>mínimo de 10 MB</strong> por tabla consultada</td>\n</tr>\n<tr>\n<td><strong>Costo on-demand</strong></td>\n<td>Bytes facturados × USD 6,25 por TiB (precio de lista; el primer TiB del mes es gratis)</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 3 — Cambiar a SELECT *</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q02-estrella.webp\" alt=\"SELECT * (1) - el validador sube a 268 KB (2): ahora lee todas las columnas\" loading=\"lazy\"><figcaption>SELECT * (1) - el validador sube a 268 KB (2): ahora lee todas las columnas</figcaption></figure>\n\n\n<p>Mismas filas, <strong>cuatro veces más datos</strong> leídos: el costo de BigQuery depende de <strong>qué columnas</strong> nombras, no de cuántas filas devuelves.</p>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">💡 El hábito</div>\n\n<p>Antes de cada <strong>Run</strong>, mira el validador. Si dice GB o TB y esperabas KB, algo está mal: falta un filtro o sobra un <code>*</code>.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Usar <code>SELECT *</code> &quot;para ver qué hay&quot;.</strong> Lee todas las columnas y se paga entero; para mirar datos está la vista previa, que es gratis.</li>\n<li><strong>Estimar el costo por las filas del resultado.</strong> Lo que cuenta son los bytes procesados, que aparecen en el validador y en la información del job.</li>\n<li><strong>Olvidar el mínimo facturado.</strong> Cada tabla leída factura al menos 10 MB, aunque la consulta lea menos.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Escribiste, estimaste y ejecutaste una consulta.</li>\n<li>Lees la información del job.</li>\n<li>Viste el costo de <code>SELECT *</code>.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-la-primera-consulta-y-los-bytes-ej1","opciones":[{"text":"Ninguna: son dos nombres del mismo número","ok":false},{"text":"Los facturados se redondean y tienen un mínimo de 10 MB por tabla","ok":true},{"text":"Los facturados son siempre la mitad","ok":false},{"text":"Los procesados incluyen el resultado","ok":false}],"enunciado":"<p>¿Qué diferencia hay entre bytes procesados y facturados?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-la-primera-consulta-y-los-bytes-ej2","opciones":[{"text":"Porque lee todas las columnas y BigQuery cobra por columnas leídas","ok":true},{"text":"Porque devuelve más filas","ok":false},{"text":"Porque desactiva la caché","ok":false},{"text":"Porque cambia de proyecto","ok":false}],"enunciado":"<p>¿Por qué SELECT * hizo subir la estimación?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-la-primera-consulta-y-los-bytes-ej3","opciones":[{"text":"Una sesión abierta en la consola","ok":false},{"text":"Cada consulta, carga o copia que ejecuta BigQuery","ok":true},{"text":"Una tabla temporal","ok":false},{"text":"Un dataset","ok":false}],"enunciado":"<p>¿Qué es un job en BigQuery?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-la-primera-consulta-y-los-bytes-ej4","opciones":[{"text":"USD 0,05","ok":false},{"text":"USD 6,25","ok":true},{"text":"USD 100","ok":false},{"text":"USD 1, igual que una carga por lotes","ok":false}],"enunciado":"<p>¿Cuánto cuesta (precio de lista on-demand) procesar 1 TiB?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true}]},"bigquery-paso-a-paso-explorar-tablas":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Mirar el menú antes de pedir</div>\n\n<p>El esquema, los detalles y la vista previa son el menú: mirarlos no cuesta nada. Pedir el plato es ejecutar una consulta, y ahí sí se paga por todo lo que la cocina tiene que leer.</p>\n</div>\n\n\n<h2>Paso 1 — El esquema</h2>\n<p>Explorador → <code>tienda</code> → <code>pedidos</code>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q03-schema.webp\" alt=\"Las pestañas Schema, Details y Preview (1) y cada columna con su tipo, modo y tamaño (2)\" loading=\"lazy\"><figcaption>Las pestañas Schema, Details y Preview (1) y cada columna con su tipo, modo y tamaño (2)</figcaption></figure>\n\n\n<p>La barra de tamaño muestra cuánto pesa cada columna: <code>metodo_pago</code> y <code>estado</code> (texto) pesan más que <code>pedido_id</code> (número). Una consulta que solo toca <code>canal</code> paga solo esa barra.</p>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Tipo de GoogleSQL</th>\n<th>Para</th>\n</tr>\n</thead><tbody><tr>\n<td><code>INT64</code>, <code>NUMERIC</code>, <code>FLOAT64</code></td>\n<td>Enteros, decimales exactos, decimales aproximados</td>\n</tr>\n<tr>\n<td><code>STRING</code></td>\n<td>Texto</td>\n</tr>\n<tr>\n<td><code>DATE</code>, <code>DATETIME</code>, <code>TIMESTAMP</code></td>\n<td>Fecha, fecha y hora local, instante (UTC)</td>\n</tr>\n<tr>\n<td><code>BOOL</code></td>\n<td>Verdadero o falso</td>\n</tr>\n<tr>\n<td><code>STRUCT</code>, <code>ARRAY</code>, <code>JSON</code></td>\n<td>Datos anidados y semiestructurados (nivel 3)</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 2 — Los detalles</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q03-details.webp\" alt=\"Details - 12.000 filas, 693 KB, particionada por día en fecha_pedido y con clustering por canal\" loading=\"lazy\"><figcaption>Details - 12.000 filas, 693 KB, particionada por día en fecha_pedido y con clustering por canal</figcaption></figure>\n\n\n<p><code>pedidos</code> viene <strong>particionada</strong> por <code>fecha_pedido</code> y con <strong>clustering</strong> por <code>canal</code>: por eso las consultas que filtran por fecha leen menos (nivel 3).</p>\n<h2>Paso 3 — Vista previa</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q03-preview.webp\" alt=\"Preview - las primeras filas sin ejecutar una consulta\" loading=\"lazy\"><figcaption>Preview - las primeras filas sin ejecutar una consulta</figcaption></figure>\n\n\n<div class=\"callout callout-cuidado\"><div class=\"callout-title\">⚠️ Preview es gratis, LIMIT no</div>\n\n<p>La pestaña <strong>Preview</strong> lee la tabla sin un job de consulta: <strong>no cuesta</strong>. En cambio <code>SELECT * FROM pedidos LIMIT 10</code> procesa <strong>todas</strong> las columnas de toda la tabla: <code>LIMIT</code> recorta el resultado, no lo que se lee.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Explorar con <code>LIMIT</code>.</strong> <code>SELECT * ... LIMIT 10</code> lee todas las columnas de toda la tabla; la vista previa muestra filas gratis.</li>\n<li><strong>Escribir tipos de otros motores.</strong> En GoogleSQL no existe <code>VARCHAR(255)</code>: el texto es <code>STRING</code> y los enteros son <code>INT64</code>.</li>\n<li><strong>Filtrar sin mirar los detalles.</strong> Si la tabla está particionada o tiene clustering, filtrar por esas columnas es lo que baja el costo; los detalles te lo dicen antes de escribir.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Lees el esquema y el tamaño de cada columna.</li>\n<li>Interpretas los detalles de una tabla.</li>\n<li>Usas Preview para mirar sin pagar.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-explorar-tablas-ej1","opciones":[{"text":"Cuánto pesa esa columna, que es lo que paga una consulta que la lee","ok":true},{"text":"Cuántos valores nulos tiene","ok":false},{"text":"Su posición en la tabla","ok":false},{"text":"Cuántas veces se consultó esa columna este mes","ok":false}],"enunciado":"<p>¿Qué indica la barra de tamaño de cada columna en el esquema?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-explorar-tablas-ej2","opciones":[{"text":"Porque muestra datos falsos","ok":false},{"text":"Porque lee la tabla sin ejecutar un job de consulta","ok":true},{"text":"Porque solo funciona en tablas chicas","ok":false},{"text":"Porque usa la caché de la última consulta","ok":false}],"enunciado":"<p>¿Por qué la pestaña Preview es gratis?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-explorar-tablas-ej3","opciones":[{"text":"Solo 10 filas","ok":false},{"text":"Todas las columnas de toda la tabla","ok":true},{"text":"Solo las columnas usadas en el ORDER BY","ok":false},{"text":"Solo la primera columna","ok":false}],"enunciado":"<p>¿Cuánto procesa <code>SELECT * FROM pedidos LIMIT 10</code>?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-explorar-tablas-ej4","opciones":[{"text":"VARCHAR(255)","ok":false},{"text":"STRING","ok":true},{"text":"TEXT","ok":false},{"text":"CHAR","ok":false}],"enunciado":"<p>¿Qué tipo de GoogleSQL guarda texto?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true}]},"bigquery-paso-a-paso-proyecto-pedidos-por-mes-y-canal":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El pedido</div>\n\n<p>Comercial: <em>&quot;Quiero ver, mes a mes desde julio, cuántos pedidos entraron por web, app y tienda, y el total. En una tabla, una fila por mes.&quot;</em></p>\n</div>\n\n\n<h2>Paso 1 — La consulta</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT DATE_TRUNC(fecha_pedido, MONTH) AS mes,\n       COUNTIF(canal = 'web') AS web,\n       COUNTIF(canal = 'app') AS app,\n       COUNTIF(canal = 'tienda') AS tienda,\n       COUNT(*) AS total\nFROM `tienda-andina-dev.tienda.pedidos`\nWHERE fecha_pedido &gt;= '2024-07-01'\nGROUP BY mes\nORDER BY mes;</code></pre>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Parte</th>\n<th>Qué hace</th>\n</tr>\n</thead><tbody><tr>\n<td><code>DATE_TRUNC(fecha_pedido, MONTH)</code></td>\n<td>Lleva cada fecha al primer día de su mes</td>\n</tr>\n<tr>\n<td><code>COUNTIF(condición)</code></td>\n<td>Cuenta solo las filas que cumplen la condición: una columna por canal</td>\n</tr>\n<tr>\n<td><code>WHERE fecha_pedido &gt;= &#39;2024-07-01&#39;</code></td>\n<td>Filtra por la columna de partición: lee menos datos</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 2 — El resultado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q04-resultado.webp\" alt=\"La consulta (1) y una fila por mes con los pedidos por canal y el total (2)\" loading=\"lazy\"><figcaption>La consulta (1) y una fila por mes con los pedidos por canal y el total (2)</figcaption></figure>\n\n\n<p>El validador marca unos 15 KB: mucho menos que la tabla entera, porque lee 2 columnas y solo las particiones desde julio.</p>\n<h2>Paso 3 — Un error a propósito</h2>\n<p>Escribe <code>FROM pedidos</code> sin el dataset:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q04-error.webp\" alt=\"El validador avisa antes de ejecutar - Table &quot;pedidos&quot; must be qualified with a dataset\" loading=\"lazy\"><figcaption>El validador avisa antes de ejecutar - Table &quot;pedidos&quot; must be qualified with a dataset</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Error típico</th>\n<th>Causa</th>\n</tr>\n</thead><tbody><tr>\n<td><code>must be qualified with a dataset</code></td>\n<td>Falta el dataset: <code>tienda.pedidos</code></td>\n</tr>\n<tr>\n<td><code>Not found: Table ...</code></td>\n<td>El nombre está mal o el dataset está en otra región</td>\n</tr>\n<tr>\n<td><code>Unrecognized name: x</code></td>\n<td>Esa columna no existe (o el alias está mal)</td>\n</tr>\n<tr>\n<td><code>SELECT list expression references column x which is neither grouped nor aggregated</code></td>\n<td>Falta <code>x</code> en el <code>GROUP BY</code></td>\n</tr>\n</tbody></table></div>\n<p>El validador muestra el error <strong>antes</strong> de gastar nada.</p>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Envolver la fecha en una función para filtrar</strong> (<code>EXTRACT(MONTH FROM fecha_pedido) &gt;= 7</code>): la consulta funciona, pero BigQuery ya no puede descartar particiones y lee más.</li>\n<li><strong>Olvidar el dataset en el nombre de la tabla.</strong> <code>FROM pedidos</code> falla con &quot;must be qualified with a dataset&quot;; va <code>FROM tienda.pedidos</code>.</li>\n<li><strong>Reemplazar <code>COUNTIF</code> por <code>WHERE canal = &#39;web&#39;</code>.</strong> El <code>WHERE</code> elimina las filas de los otros canales y ya no puedes contar los tres en la misma consulta.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lista de verificación</h2>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Una fila por mes desde julio de 2024.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Columnas web, app, tienda y total.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  La estimación es de KB, no de la tabla entera.</li>\n</ul>\n<h2>Lo que aprendiste en el nivel 1</h2>\n<ul>\n<li>Qué es BigQuery y Studio.</li>\n<li>Consultas, estimación de bytes y la información del job.</li>\n<li>Esquema, detalles, Preview y errores.</li>\n</ul>\n<p>En el nivel 2: datasets, tablas, costos, caché y el historial de jobs.</p>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-pedidos-por-mes-y-canal-ej1","opciones":[{"text":"2024-11-01","ok":true},{"text":"2024-11-30","ok":false},{"text":"2024-11-17 a las 00:00","ok":false},{"text":"2024-12-01","ok":false}],"enunciado":"<p>¿Qué devuelve DATE_TRUNC(&#39;2024-11-17&#39;, MONTH)?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-pedidos-por-mes-y-canal-ej2","opciones":[{"text":"Cuenta todas las filas","ok":false},{"text":"Cuenta solo las filas cuyo canal es web","ok":true},{"text":"Filtra la tabla","ok":false},{"text":"Da error","ok":false}],"enunciado":"<p>¿Qué hace COUNTIF(canal = &#39;web&#39;)?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-pedidos-por-mes-y-canal-ej3","opciones":[{"text":"Porque usa pocas columnas y filtra por la columna de partición","ok":true},{"text":"Porque la tabla está vacía","ok":false},{"text":"Porque usa LIMIT","ok":false},{"text":"Porque la caché devuelve cualquier consulta por 0 bytes","ok":false}],"enunciado":"<p>¿Por qué la consulta leyó solo unos KB?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-pedidos-por-mes-y-canal-ej4","opciones":[{"text":"Un warehouse","ok":false},{"text":"El nombre del dataset: tienda.pedidos","ok":true},{"text":"El rol BigQuery Job User","ok":false},{"text":"Un GROUP BY por canal","ok":false}],"enunciado":"<p>&quot;Table &quot;pedidos&quot; must be qualified with a dataset&quot;. ¿Qué falta?</p>\n","dificultad":"1 · Básico","dificultadLeccion":true}]},"bigquery-paso-a-paso-datasets-y-tablas":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Una carpeta con dirección y candado</div>\n\n<p>Un dataset es una carpeta con <strong>dirección</strong> (la región, que no se puede mudar) y <strong>candado</strong> (los permisos, que se ponen a la carpeta y valen para lo que tiene adentro). Por eso conviene pensar dónde va a vivir y quién la va a abrir antes de crearla.</p>\n</div>\n\n\n<h2>Paso 1 — Crear el dataset y una tabla</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE SCHEMA analitica\nOPTIONS (description = 'Tablas limpias para el negocio');\n\nCREATE TABLE analitica.ventas_por_canal AS\nSELECT canal, COUNT(*) AS pedidos\nFROM tienda.pedidos\nWHERE fecha_pedido &gt;= '2024-01-01'\nGROUP BY canal;</code></pre>\n<p>En GoogleSQL, <strong><code>CREATE SCHEMA</code> crea un dataset</strong> (también se crea con el <strong>+</strong> del explorador).</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q05-crear.webp\" alt=\"El dataset analitica en el explorador (1), las dos sentencias ejecutadas (2) y la tabla creada (3)\" loading=\"lazy\"><figcaption>El dataset analitica en el explorador (1), las dos sentencias ejecutadas (2) y la tabla creada (3)</figcaption></figure>\n\n\n<h2>Paso 2 — La página del dataset</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q05-dataset.webp\" alt=\"El dataset analitica (1) y sus tablas con tipo, filas y tamaño (2)\" loading=\"lazy\"><figcaption>El dataset analitica (1) y sus tablas con tipo, filas y tamaño (2)</figcaption></figure>\n\n\n<h2>Paso 3 — Qué define un dataset</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Propiedad</th>\n<th>Qué decide</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Ubicación (región)</strong></td>\n<td>Dónde viven los datos: <code>US</code>, <code>EU</code>, <code>southamerica-east1</code>… No se cambia después</td>\n</tr>\n<tr>\n<td><strong>Permisos</strong></td>\n<td>Quién puede leer o escribir sus tablas (nivel 5)</td>\n</tr>\n<tr>\n<td><strong>Vencimiento por defecto</strong></td>\n<td>Tablas que se borran solas después de N días (útil para datos temporales)</td>\n</tr>\n<tr>\n<td><strong>Descripción y etiquetas</strong></td>\n<td>Documentación y costos por equipo</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-cuidado\"><div class=\"callout-title\">⚠️ La región importa</div>\n\n<p>Una consulta solo puede unir tablas de <strong>la misma región</strong>. Elige la región al crear el dataset pensando dónde están los demás datos (y, si aplica, dónde exige la ley que estén).</p>\n</div>\n\n\n<h2>Paso 4 — Cómo organizar</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Dataset</th>\n<th>Para</th>\n</tr>\n</thead><tbody><tr>\n<td><code>raw_*</code></td>\n<td>Datos tal como llegan</td>\n</tr>\n<tr>\n<td><code>staging</code></td>\n<td>Limpieza intermedia</td>\n</tr>\n<tr>\n<td><code>analitica</code> / <code>marts</code></td>\n<td>Tablas listas para el negocio</td>\n</tr>\n<tr>\n<td><code>reportes</code></td>\n<td>Vistas para cada área</td>\n</tr>\n<tr>\n<td><code>sandbox_&lt;persona&gt;</code></td>\n<td>Pruebas personales, con vencimiento corto</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Crear el dataset en otra región que los demás datos.</strong> Después no se puede unir con ellos y la región no se cambia: hay que crear otro dataset y copiar.</li>\n<li><strong>Meter todo en un solo dataset.</strong> Los permisos se dan por dataset; si raw, analítica y reportes están juntos, no puedes dar acceso solo a los reportes.</li>\n<li><strong>Datasets de prueba sin vencimiento.</strong> Las tablas olvidadas siguen cobrando almacenamiento; un vencimiento por defecto las limpia solas.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Creaste un dataset y una tabla.</li>\n<li>Sabes qué define un dataset.</li>\n<li>Tienes una forma de organizar el proyecto.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-datasets-y-tablas-ej1","opciones":[{"text":"CREATE DATABASE","ok":false},{"text":"CREATE SCHEMA","ok":true},{"text":"CREATE DATASET TABLE","ok":false},{"text":"NEW DATASET","ok":false}],"enunciado":"<p>¿Qué sentencia de GoogleSQL crea un dataset?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-datasets-y-tablas-ej2","opciones":[{"text":"Sí, desde Details","ok":false},{"text":"No: hay que crear otro y copiar los datos","ok":true},{"text":"Sí, con ALTER SCHEMA SET OPTIONS (location = ...)","ok":false},{"text":"Sí, pero solo si el dataset está vacío","ok":false}],"enunciado":"<p>¿Se puede cambiar la región de un dataset después de crearlo?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-datasets-y-tablas-ej3","opciones":[{"text":"Sí, siempre","ok":false},{"text":"No: las tablas de una consulta tienen que estar en la misma región","ok":true},{"text":"Sí, si usas el nombre completo proyecto.dataset.tabla","ok":false},{"text":"Solo si las dos tablas son vistas","ok":false}],"enunciado":"<p>¿Puedes unir una tabla en US con una en EU en la misma consulta?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-datasets-y-tablas-ej4","opciones":[{"text":"Para que las tablas se borren solas después de N días","ok":true},{"text":"Para hacer backups","ok":false},{"text":"Para cambiar la región","ok":false},{"text":"Para mover las tablas a almacenamiento de largo plazo","ok":false}],"enunciado":"<p>¿Para qué sirve el vencimiento por defecto de un dataset?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true}]},"bigquery-paso-a-paso-costos-limit-y-cache":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 La olla y la porción</div>\n\n<p><code>LIMIT</code> es pedir que te sirvan una porción de una olla que igual se cocinó entera: pagas toda la olla. La caché es recalentar lo que ya cocinaste: si la consulta es idéntica y la tabla no cambió, sale gratis.</p>\n</div>\n\n\n<h2>Paso 1 — LIMIT no ahorra</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT *\nFROM tienda.pedidos\nWHERE fecha_pedido &gt;= '2024-01-01'\nLIMIT 10;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q06-limit.webp\" alt=\"SELECT * con LIMIT 10 (1) - el validador sigue marcando 268 KB (2)\" loading=\"lazy\"><figcaption>SELECT * con LIMIT 10 (1) - el validador sigue marcando 268 KB (2)</figcaption></figure>\n\n\n<p><code>LIMIT</code> corta el resultado <strong>después</strong> de leer las columnas. Para mirar datos, usa <strong>Preview</strong> (gratis).</p>\n<h2>Paso 2 — La caché</h2>\n<p>Ejecuta una consulta y vuelve a ejecutarla sin cambios:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q06-cache.webp\" alt=\"La segunda ejecución - 0 B procesados y la marca &quot;results cached&quot;\" loading=\"lazy\"><figcaption>La segunda ejecución - 0 B procesados y la marca &quot;results cached&quot;</figcaption></figure>\n\n\n<p>BigQuery guarda el resultado <strong>24 horas</strong>. Si la consulta es idéntica, las tablas no cambiaron y no usa funciones no deterministas (<code>CURRENT_TIMESTAMP()</code>, <code>RAND()</code>), responde desde la caché <strong>sin costo</strong>.</p>\n<h2>Paso 3 — La página de costos</h2>\n<p><strong>Costs (práctica)</strong>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q06-costos.webp\" alt=\"Bytes procesados, facturados y costo de la práctica (1) y tus consultas más caras con lo que costarían si las tablas fueran 10.000 veces más grandes (2)\" loading=\"lazy\"><figcaption>Bytes procesados, facturados y costo de la práctica (1) y tus consultas más caras con lo que costarían si las tablas fueran 10.000 veces más grandes (2)</figcaption></figure>\n\n\n<h2>Paso 4 — Los modelos de precio</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Concepto</th>\n<th>Cómo se cobra (precios de lista, varían por región)</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>On-demand</strong></td>\n<td>USD 6,25 por TiB procesado; el primer TiB del mes es gratis</td>\n</tr>\n<tr>\n<td><strong>Capacidad (ediciones)</strong></td>\n<td>Slots reservados o con autoescalado por hora (Standard, Enterprise, Enterprise Plus): costo predecible para mucho volumen</td>\n</tr>\n<tr>\n<td><strong>Almacenamiento activo</strong></td>\n<td>Por GiB al mes</td>\n</tr>\n<tr>\n<td><strong>Almacenamiento de largo plazo</strong></td>\n<td>Si una tabla o partición no se modifica en 90 días, su precio baja a la mitad, solo</td>\n</tr>\n<tr>\n<td><strong>Cargas por lotes</strong></td>\n<td>Gratis (se paga el almacenamiento)</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">💡 Un tope para dormir tranquilo</div>\n\n<p>En BigQuery real se puede fijar <strong>Maximum bytes billed</strong> en cada consulta (o un máximo por día por proyecto o usuario): si la consulta superaría ese límite, falla sin cobrar.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Poner <code>LIMIT</code> para ahorrar.</strong> Recorta el resultado, no la lectura. Lo que ahorra es nombrar menos columnas y filtrar por la partición.</li>\n<li><strong>Esperar la caché con funciones no deterministas.</strong> Una consulta con <code>CURRENT_TIMESTAMP()</code> o sobre una tabla que cambió no sale de la caché.</li>\n<li><strong>Trabajar sin tope de bytes.</strong> Sin <em>maximum bytes billed</em>, un error en un filtro puede leer terabytes; con el tope, la consulta falla antes de cobrar.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Comprobaste que LIMIT no ahorra.</li>\n<li>Viste la caché en acción.</li>\n<li>Conoces los modelos de precio.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-costos-limit-y-cache-ej1","opciones":[{"text":"Una décima parte","ok":false},{"text":"Lo mismo: LIMIT recorta el resultado, no la lectura","ok":true},{"text":"Solo las columnas del ORDER BY","ok":false},{"text":"El doble","ok":false}],"enunciado":"<p>¿Cuánto procesa <code>SELECT * FROM pedidos LIMIT 10</code> frente a <code>SELECT *</code> sin LIMIT?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-costos-limit-y-cache-ej2","opciones":[{"text":"Si la consulta es idéntica, las tablas no cambiaron y es determinista, dentro de 24 horas","ok":true},{"text":"Siempre que la consulta sea parecida, aunque cambien los datos","ok":false},{"text":"Solo si la consulta tiene LIMIT","ok":false},{"text":"Solo durante la primera hora después de ejecutarla","ok":false}],"enunciado":"<p>¿Cuándo responde BigQuery desde la caché?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-costos-limit-y-cache-ej3","opciones":[{"text":"Se borra","ok":false},{"text":"Pasa a almacenamiento de largo plazo y cuesta la mitad","ok":true},{"text":"Sube, porque se considera archivada","ok":false},{"text":"Se mueve sola a Cloud Storage","ok":false}],"enunciado":"<p>¿Qué pasa con el precio de una tabla que no se modifica en 90 días?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-costos-limit-y-cache-ej4","opciones":[{"text":"La carga es gratis; se paga el almacenamiento","ok":true},{"text":"USD 6,25 por TiB","ok":false},{"text":"Una tarifa fija","ok":false},{"text":"Lo mismo que consultar esos bytes","ok":false}],"enunciado":"<p>¿Cuánto cuesta cargar un archivo por lotes a BigQuery?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true}]},"bigquery-paso-a-paso-historial-de-jobs":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 La libreta de la caja</div>\n\n<p>El historial de jobs es la libreta donde la caja anota cada operación: quién la hizo, cuándo, cuánto leyó y si salió bien. Cuando algo falla o la factura sube, la respuesta está anotada ahí.</p>\n</div>\n\n\n<h2>Paso 1 — El historial</h2>\n<p><strong>Jobs explorer</strong>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q07-jobs.webp\" alt=\"Cada job con su estado, tipo, SQL, bytes procesados y facturados, duración y cuándo se creó\" loading=\"lazy\"><figcaption>Cada job con su estado, tipo, SQL, bytes procesados y facturados, duración y cuándo se creó</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Tipo de job</th>\n<th>Qué es</th>\n</tr>\n</thead><tbody><tr>\n<td><code>QUERY</code></td>\n<td>Una consulta, incluidos CREATE, INSERT, MERGE</td>\n</tr>\n<tr>\n<td><code>LOAD</code></td>\n<td>Una carga de archivos</td>\n</tr>\n<tr>\n<td><code>EXTRACT</code></td>\n<td>Una exportación a Cloud Storage</td>\n</tr>\n<tr>\n<td><code>COPY</code></td>\n<td>Una copia de tabla</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 2 — El detalle</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q07-detalle.webp\" alt=\"El detalle de un job - el SQL, los bytes (0 B, results cached), qué se leyó y Open as new query\" loading=\"lazy\"><figcaption>El detalle de un job - el SQL, los bytes (0 B, results cached), qué se leyó y Open as new query</figcaption></figure>\n\n\n<p><strong>Open as new query</strong> abre el SQL en una pestaña nueva: útil para repetir o corregir lo que hizo otra persona.</p>\n<h2>Paso 3 — Para qué sirve</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Pregunta</th>\n<th>Qué mirar</th>\n</tr>\n</thead><tbody><tr>\n<td>¿Por qué falló la carga de anoche?</td>\n<td>Jobs en error y su mensaje</td>\n</tr>\n<tr>\n<td>¿Qué consulta gasta más?</td>\n<td>Ordenar por <strong>Billed</strong></td>\n</tr>\n<tr>\n<td>¿Se está aprovechando la caché?</td>\n<td>La marca <em>cache</em></td>\n</tr>\n<tr>\n<td>¿Quién corre esa consulta tan cara?</td>\n<td>El usuario del job (en BigQuery real, con permisos de administrador)</td>\n</tr>\n</tbody></table></div>\n<p>Un job que falla en la validación (un error de sintaxis o de nombre) <strong>no cobra</strong>. Para analizar los jobs con SQL, existe <code>INFORMATION_SCHEMA.JOBS</code> (nivel 5).</p>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Volver a ejecutar a ciegas una consulta que falló.</strong> El detalle del job tiene el mensaje de error y la línea; léelo antes de reintentar.</li>\n<li><strong>Confundir bytes procesados con facturados.</strong> Los facturados son los que se cobran: redondeados y con un mínimo por tabla.</li>\n<li><strong>Repetir una consulta cara sin revisarla.</strong> Ábrela como consulta nueva desde el historial, mira qué columnas y filtros usa, y optimízala antes de correrla otra vez.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Lees el historial de jobs.</li>\n<li>Abres y reabres un job.</li>\n<li>Sabes usarlo para encontrar lo caro.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-historial-de-jobs-ej1","opciones":[{"text":"QUERY","ok":true},{"text":"LOAD","ok":false},{"text":"COPY","ok":false},{"text":"EXTRACT","ok":false}],"enunciado":"<p>¿Qué tipo de job es un INSERT?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-historial-de-jobs-ej2","opciones":[{"text":"Tiene más bytes facturados que procesados","ok":false},{"text":"Tiene 0 B procesados y la marca de caché","ok":true},{"text":"Está en rojo","ok":false},{"text":"Aparece con tipo COPY","ok":false}],"enunciado":"<p>¿Cómo reconoces un job que salió de la caché?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-historial-de-jobs-ej3","opciones":[{"text":"Lo vuelve a ejecutar con los mismos parámetros","ok":false},{"text":"Abre el SQL del job en una pestaña nueva","ok":true},{"text":"Repite el job automáticamente cada día","ok":false},{"text":"Exporta el resultado","ok":false}],"enunciado":"<p>¿Qué hace Open as new query?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-historial-de-jobs-ej4","opciones":[{"text":"Sí, el mínimo de 10 MB","ok":false},{"text":"No","ok":true},{"text":"Sí, lo que hubiera procesado si funcionaba","ok":false},{"text":"Sí, si la tabla es grande","ok":false}],"enunciado":"<p>¿Cobra BigQuery por un job que falla por un error de sintaxis?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true}]},"bigquery-paso-a-paso-proyecto-dataset-de-analitica":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El pedido</div>\n\n<p>Lucía, líder de datos: <em>&quot;Quiero <code>analitica</code> con dos tablas: pedidos por canal desde 2024 y clientes por país. Que el script se pueda volver a correr sin errores, y mostrame el inventario con una consulta.&quot;</em></p>\n</div>\n\n\n<h2>Lo que tienes que lograr</h2>\n<ol>\n<li><code>analitica.ventas_por_canal</code> (ya la tienes) y <code>analitica.clientes_por_pais</code>.</li>\n<li>Un script que se pueda correr dos veces.</li>\n<li>El inventario del dataset con SQL.</li>\n</ol>\n<details><summary>💡 Pista 1: repetir sin errores</summary>\n\n<p><code>CREATE OR REPLACE TABLE</code> reemplaza la tabla si existe; <code>CREATE SCHEMA IF NOT EXISTS</code> no falla si el dataset ya está.</p>\n</details>\n\n<details><summary>💡 Pista 2: el inventario</summary>\n\n<p>Cada dataset tiene vistas de sistema: <code>analitica.INFORMATION_SCHEMA.TABLES</code> lista sus tablas y vistas.</p>\n</details>\n\n<h2>Cómo se ve terminado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q08-inventario.webp\" alt=\"El script (1) y el inventario - clientes_por_pais con 11 filas y ventas_por_canal con 4 (2)\" loading=\"lazy\"><figcaption>El script (1) y el inventario - clientes_por_pais con 11 filas y ventas_por_canal con 4 (2)</figcaption></figure>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Crear las tablas con clics en la consola.</strong> Nadie puede repetirlo igual; un script con <code>CREATE OR REPLACE</code> se versiona y se vuelve a correr.</li>\n<li><strong>Usar <code>CREATE TABLE</code> sin <code>OR REPLACE</code> en un script.</strong> La segunda vez falla porque la tabla ya existe.</li>\n<li><strong>Verificar mirando el explorador.</strong> Una consulta a <code>INFORMATION_SCHEMA.TABLES</code> deja la verificación escrita y se puede automatizar.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lista de verificación</h2>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  <code>analitica</code> tiene las dos tablas.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Correr el script dos veces no da error.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  La consulta a <code>INFORMATION_SCHEMA.TABLES</code> las lista.</li>\n</ul>\n<details><summary>💡 Solución comentada</summary>\n\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE SCHEMA IF NOT EXISTS analitica\nOPTIONS (description = 'Tablas limpias para el negocio');\n\nCREATE OR REPLACE TABLE analitica.ventas_por_canal AS\nSELECT canal, COUNT(*) AS pedidos\nFROM tienda.pedidos\nWHERE fecha_pedido &gt;= '2024-01-01'\nGROUP BY canal;\n\nCREATE OR REPLACE TABLE analitica.clientes_por_pais AS\nSELECT pais, COUNT(*) AS clientes\nFROM tienda.clientes\nGROUP BY pais;\n\nSELECT table_name, table_type, row_count\nFROM analitica.INFORMATION_SCHEMA.TABLES\nORDER BY table_name;</code></pre>\n<p><strong>Por qué INFORMATION_SCHEMA:</strong> lo que se comprueba con SQL se puede automatizar (una prueba en el CI que falle si falta una tabla). Mirar a mano no escala.</p>\n</details>\n\n<h2>Lo que aprendiste en el nivel 2</h2>\n<ul>\n<li>Datasets, regiones y organización.</li>\n<li>Costos, LIMIT, caché y precios.</li>\n<li>El historial de jobs.</li>\n</ul>\n<p>En el nivel 3: particiones, clustering, cargas y datos anidados.</p>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-dataset-de-analitica-ej1","opciones":[{"text":"Crea la tabla o la reemplaza si ya existe","ok":true},{"text":"Falla si existe","ok":false},{"text":"Agrega filas","ok":false},{"text":"Crea una vista","ok":false}],"enunciado":"<p>¿Qué hace CREATE OR REPLACE TABLE?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-dataset-de-analitica-ej2","opciones":[{"text":"SHOW TABLES","ok":false},{"text":"SELECT ... FROM analitica.INFORMATION_SCHEMA.TABLES","ok":true},{"text":"LIST analitica","ok":false},{"text":"DESCRIBE analitica","ok":false}],"enunciado":"<p>¿Cómo listas las tablas de un dataset con SQL?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-dataset-de-analitica-ej3","opciones":[{"text":"Porque cuesta menos","ok":false},{"text":"Porque se puede automatizar y volver a correr sin romper nada","ok":true},{"text":"Porque BigQuery lo exige","ok":false},{"text":"Porque así no hace falta elegir la región","ok":false}],"enunciado":"<p>¿Por qué conviene un script que se pueda repetir?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-dataset-de-analitica-ej4","opciones":[{"text":"TABLE","ok":false},{"text":"VIEW","ok":true},{"text":"BASE TABLE","ok":false},{"text":"SNAPSHOT","ok":false}],"enunciado":"<p>¿Qué devuelve table_type para una vista?</p>\n","dificultad":"2 · Básico-intermedio","dificultadLeccion":true}]},"bigquery-paso-a-paso-particiones-y-clustering":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Estantes por fecha y libros por tema</div>\n\n<p>Una tabla particionada es una biblioteca con un estante por día: si pides solo diciembre, nadie mira los demás estantes. El clustering ordena los libros de cada estante por tema: si además pides el canal web, se saltan los bloques que no lo tienen.</p>\n</div>\n\n\n<h2>Paso 1 — Crear la tabla</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE TABLE analitica.pedidos_part\nPARTITION BY fecha_pedido\nCLUSTER BY canal\nOPTIONS (require_partition_filter = TRUE)\nAS SELECT * FROM tienda.pedidos;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q09-crear.webp\" alt=\"La tabla particionada por fecha_pedido, con clustering por canal y filtro obligatorio (1), creada (2)\" loading=\"lazy\"><figcaption>La tabla particionada por fecha_pedido, con clustering por canal y filtro obligatorio (1), creada (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Cláusula</th>\n<th>Qué hace</th>\n</tr>\n</thead><tbody><tr>\n<td><code>PARTITION BY fecha_pedido</code></td>\n<td>Divide la tabla en una partición por día</td>\n</tr>\n<tr>\n<td><code>CLUSTER BY canal</code></td>\n<td>Ordena los datos dentro de cada partición por canal (hasta 4 columnas)</td>\n</tr>\n<tr>\n<td><code>require_partition_filter = TRUE</code></td>\n<td>Rechaza las consultas que no filtran por la partición</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 2 — La poda</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT canal, COUNT(*) AS pedidos\nFROM analitica.pedidos_part\nWHERE fecha_pedido BETWEEN '2024-11-01' AND '2024-11-30'\nGROUP BY canal;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q09-poda.webp\" alt=\"El filtro por un mes (1) - el validador baja a 7,41 KB (2): solo se leen las particiones de noviembre\" loading=\"lazy\"><figcaption>El filtro por un mes (1) - el validador baja a 7,41 KB (2): solo se leen las particiones de noviembre</figcaption></figure>\n\n\n<p>Sin el filtro:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q09-sin-filtro.webp\" alt=\"Cannot query over table without a filter over column(s) 'fecha_pedido' - el filtro obligatorio frena la consulta cara\" loading=\"lazy\"><figcaption>Cannot query over table without a filter over column(s) 'fecha_pedido' - el filtro obligatorio frena la consulta cara</figcaption></figure>\n\n\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q09-details.webp\" alt=\"Details - particionada por DAY en fecha_pedido, filtro de partición Required y clustering por canal\" loading=\"lazy\"><figcaption>Details - particionada por DAY en fecha_pedido, filtro de partición Required y clustering por canal</figcaption></figure>\n\n\n<h2>Paso 3 — Qué impide la poda</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Filtro</th>\n<th>¿Poda?</th>\n</tr>\n</thead><tbody><tr>\n<td><code>WHERE fecha_pedido = &#39;2024-11-17&#39;</code></td>\n<td>✅</td>\n</tr>\n<tr>\n<td><code>WHERE fecha_pedido BETWEEN &#39;2024-11-01&#39; AND &#39;2024-11-30&#39;</code></td>\n<td>✅</td>\n</tr>\n<tr>\n<td><code>WHERE EXTRACT(YEAR FROM fecha_pedido) = 2024</code></td>\n<td>❌ la función oculta la columna</td>\n</tr>\n<tr>\n<td><code>WHERE CAST(fecha_pedido AS STRING) LIKE &#39;2024%&#39;</code></td>\n<td>❌</td>\n</tr>\n<tr>\n<td><code>WHERE fecha_pedido &gt;= (SELECT MAX(fecha) FROM otra)</code></td>\n<td>Parcial: la estimación no lo sabe de antemano</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 4 — Cuándo usar cada uno</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Técnica</th>\n<th>Conviene cuando</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Particionar</strong></td>\n<td>Casi siempre se filtra por fecha (o por un entero de rango) y la tabla es grande</td>\n</tr>\n<tr>\n<td><strong>Clustering</strong></td>\n<td>Se filtra o agrupa seguido por otras columnas (canal, país, cliente). No baja la estimación, sí lo que finalmente se cobra</td>\n</tr>\n<tr>\n<td><strong>Ambos</strong></td>\n<td>Tablas de hechos grandes: particionar por fecha y clustering por las dimensiones más filtradas</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Envolver la columna de partición en una función.</strong> <code>EXTRACT(YEAR FROM fecha) = 2024</code> impide la poda; escribe <code>fecha BETWEEN &#39;2024-01-01&#39; AND &#39;2024-12-31&#39;</code>.</li>\n<li><strong>Particionar por algo que no se filtra.</strong> La partición ayuda solo si las consultas filtran por esa columna; casi siempre es la fecha del evento.</li>\n<li><strong>Clustering por columnas que nadie filtra.</strong> Ordenar por el id del pedido no ayuda si las consultas filtran por canal y país.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Creaste una tabla particionada y con clustering.</li>\n<li>Viste la poda en la estimación.</li>\n<li>Sabes qué filtros impiden la poda.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-particiones-y-clustering-ej1","opciones":[{"text":"La fecha por la que casi siempre se filtra","ok":true},{"text":"El email del cliente","ok":false},{"text":"El id del pedido, porque es único","ok":false},{"text":"El id del cliente, porque es la clave de los JOIN","ok":false}],"enunciado":"<p>¿Qué columna conviene usar para particionar una tabla de ventas?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-particiones-y-clustering-ej2","opciones":[{"text":"Borra las particiones viejas","ok":false},{"text":"Rechaza las consultas que no filtran por la columna de partición","ok":true},{"text":"Crea una partición por fila","ok":false},{"text":"Desactiva la caché","ok":false}],"enunciado":"<p>¿Qué hace require_partition_filter = TRUE?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-particiones-y-clustering-ej3","opciones":[{"text":"Porque EXTRACT solo funciona en columnas DATETIME","ok":false},{"text":"Porque la función sobre la columna impide saber qué particiones descartar","ok":true},{"text":"Porque falta un clustering por año","ok":false},{"text":"Sí poda: BigQuery reescribe la condición solo","ok":false}],"enunciado":"<p>¿Por qué <code>WHERE EXTRACT(YEAR FROM fecha_pedido) = 2024</code> no poda?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-particiones-y-clustering-ej4","opciones":[{"text":"1","ok":false},{"text":"Hasta 4","ok":true},{"text":"Hasta 100","ok":false},{"text":"Ilimitadas","ok":false}],"enunciado":"<p>¿Cuántas columnas admite CLUSTER BY?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true}]},"bigquery-paso-a-paso-cargar-datos":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Mudar los muebles o ir al depósito</div>\n\n<p>Cargar un archivo es mudar los muebles a tu casa: la mudanza es gratis, pagas el espacio y después todo está a mano. Una tabla externa es dejarlos en el depósito (Cloud Storage) e ir a buscarlos cada vez que los necesitas: más lento y sin todas las comodidades.</p>\n</div>\n\n\n<h2>Paso 1 — Create table</h2>\n<p>En el dataset <code>analitica</code>, <strong>Create table</strong>:</p>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q10-crear.webp\" alt=\"Create table - desde un archivo (aquí, el de ejemplo del curso), tabla eventos_app y partición por la columna fecha\" loading=\"lazy\"><figcaption>Create table - desde un archivo (aquí, el de ejemplo del curso), tabla eventos_app y partición por la columna fecha</figcaption></figure>\n\n\n<p>En la práctica puedes subir tu propio CSV o JSON por líneas; el de ejemplo trae 600 eventos de la app en 60 días.</p>\n<h2>Paso 2 — La tabla cargada</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q10-tabla.webp\" alt=\"eventos_app (1) - el esquema detectado con fecha como columna de partición (2)\" loading=\"lazy\"><figcaption>eventos_app (1) - el esquema detectado con fecha como columna de partición (2)</figcaption></figure>\n\n\n<p><strong>Auto detect</strong> deduce los tipos mirando los datos. Para producción conviene un <strong>esquema explícito</strong>: si mañana un archivo trae <code>&quot;N/A&quot;</code> en una columna numérica, el esquema fijo rechaza la fila en lugar de cambiar el tipo.</p>\n<h2>Paso 3 — Otras formas de cargar</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">-- con SQL, desde Cloud Storage\nLOAD DATA INTO analitica.eventos_app\nPARTITION BY fecha\nFROM FILES (format = 'CSV', skip_leading_rows = 1, uris = ['gs://tienda-andina-landing/eventos/*.csv']);</code></pre>\n<pre data-lang=\"bash\" data-norun tabindex=\"0\"><code class=\"language-bash\"># con la CLI\nbq load --source_format=CSV --skip_leading_rows=1 --time_partitioning_field=fecha \\\n  analitica.eventos_app gs://tienda-andina-landing/eventos/*.csv</code></pre>\n<details class=\"bx\"><summary>🔍 Qué hace cada comando <span>(1)</span></summary><ol><li><code class=\"bx-linea\">bq load --source_format=CSV --skip_leading_rows=1 --time_partitioning_field=fecha    analitica.eventos_app gs://tienda-andina-landing/eve…</code><span><code>bq</code>: la CLI de BigQuery. <code>load</code> carga un archivo (CSV, Parquet) en una tabla</span></li></ol><p class=\"bx-donde\">Se escribe en la <b>terminal</b>: la del curso (botón ⌨ Terminal) o la de tu computadora — <b>Terminal</b> en macOS, <b>Ubuntu (WSL)</b> o <b>Git Bash</b> en Windows. Escribe una línea y presiona Enter.</p></details>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Forma</th>\n<th>Cuándo</th>\n<th>Costo</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Carga por lotes</strong> (Create table, <code>LOAD DATA</code>, <code>bq load</code>)</td>\n<td>Archivos que llegan cada hora o cada día</td>\n<td>Gratis; se paga el almacenamiento</td>\n</tr>\n<tr>\n<td><strong>Tabla externa / BigLake</strong></td>\n<td>Consultar archivos en Cloud Storage sin cargarlos</td>\n<td>Se paga al consultarlos</td>\n</tr>\n<tr>\n<td><strong>Streaming</strong> (Storage Write API)</td>\n<td>Datos que tienen que estar al instante</td>\n<td>Por volumen ingerido</td>\n</tr>\n<tr>\n<td><strong>Data Transfer Service</strong></td>\n<td>Fuentes conocidas (Google Ads, S3, otros) a horario</td>\n<td>Según la fuente</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Autodetectar el esquema en producción.</strong> Un archivo con un valor raro puede cambiar el tipo de una columna; en producción el esquema va explícito.</li>\n<li><strong>Cargar sin partición una tabla que va a crecer.</strong> Particionarla después obliga a recrearla; decídelo al crearla.</li>\n<li><strong>Usar streaming cuando alcanza con lotes.</strong> La carga por lotes es gratis; la escritura en streaming se paga y solo tiene sentido si necesitas los datos al instante.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Creaste una tabla particionada desde un archivo.</li>\n<li>Revisaste el esquema detectado.</li>\n<li>Conoces las otras formas de cargar.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-cargar-datos-ej1","opciones":[{"text":"USD 6,25 por TiB","ok":false},{"text":"Nada: se paga el almacenamiento","ok":true},{"text":"Una tarifa por archivo","ok":false},{"text":"Lo mismo que consultar los bytes cargados","ok":false}],"enunciado":"<p>¿Cuánto cuesta una carga por lotes en BigQuery?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-cargar-datos-ej2","opciones":[{"text":"Deduce el esquema y los tipos mirando los datos del archivo","ok":true},{"text":"Borra las filas malas","ok":false},{"text":"Crea la partición sola","ok":false},{"text":"Comprime el archivo","ok":false}],"enunciado":"<p>¿Qué hace Auto detect?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-cargar-datos-ej3","opciones":[{"text":"Una tabla de otro proyecto","ok":false},{"text":"Una tabla que lee los archivos en Cloud Storage sin cargarlos a BigQuery","ok":true},{"text":"Una vista","ok":false},{"text":"Una tabla cargada en otra región","ok":false}],"enunciado":"<p>¿Qué es una tabla externa?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-cargar-datos-ej4","opciones":[{"text":"Porque autodetect cobra por cada archivo","ok":false},{"text":"Para que un archivo con datos raros falle en lugar de cambiar los tipos de la tabla","ok":true},{"text":"Porque autodetect no existe","ok":false},{"text":"Porque es más barato","ok":false}],"enunciado":"<p>¿Por qué conviene un esquema explícito en producción?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true}]},"bigquery-paso-a-paso-vistas-struct-array-y-unnest":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 El ticket con sus renglones</div>\n\n<p>En una base clásica, el ticket va en una tabla y sus renglones en otra, y cada consulta los vuelve a unir. En BigQuery el ticket puede llevar sus renglones adentro: un <code>ARRAY</code> de <code>STRUCT</code>. <code>UNNEST</code> despliega esos renglones en filas cuando los necesitas.</p>\n</div>\n\n\n<h2>Paso 1 — Una vista con un arreglo</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE OR REPLACE VIEW analitica.v_ultimos_pedidos AS\nSELECT cliente_id,\n       ARRAY_AGG(pedido_id ORDER BY fecha_pedido DESC LIMIT 3) AS ultimos\nFROM tienda.pedidos\nGROUP BY cliente_id;\n\nSELECT * FROM analitica.v_ultimos_pedidos ORDER BY cliente_id LIMIT 5;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q11-array.webp\" alt=\"La vista con ARRAY_AGG (1) - una fila por cliente con sus tres últimos pedidos en una lista (2)\" loading=\"lazy\"><figcaption>La vista con ARRAY_AGG (1) - una fila por cliente con sus tres últimos pedidos en una lista (2)</figcaption></figure>\n\n\n<p>Una <strong>vista</strong> guarda la consulta, no los datos: cada vez que se usa, se ejecuta y se cobra lo que lee de las tablas de fondo.</p>\n<h2>Paso 2 — UNNEST</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT v.cliente_id, pedido\nFROM analitica.v_ultimos_pedidos AS v,\n     UNNEST(v.ultimos) AS pedido\nWHERE v.cliente_id &lt;= 3\nORDER BY v.cliente_id;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q11-unnest.webp\" alt=\"UNNEST abre la lista (1) - una fila por pedido del cliente (2)\" loading=\"lazy\"><figcaption>UNNEST abre la lista (1) - una fila por pedido del cliente (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Función</th>\n<th>Qué hace</th>\n</tr>\n</thead><tbody><tr>\n<td><code>ARRAY_AGG(x ORDER BY y LIMIT n)</code></td>\n<td>Junta valores en una lista ordenada</td>\n</tr>\n<tr>\n<td><code>UNNEST(arreglo)</code></td>\n<td>Abre la lista: una fila por elemento</td>\n</tr>\n<tr>\n<td><code>arreglo[OFFSET(0)]</code></td>\n<td>El primer elemento (desde 0); <code>ORDINAL(1)</code> cuenta desde 1</td>\n</tr>\n<tr>\n<td><code>ARRAY_LENGTH(arreglo)</code></td>\n<td>Cuántos elementos tiene</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 3 — STRUCT</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT STRUCT('Lima Centro' AS tienda, 'PE' AS pais) AS sucursal,\n       ['web', 'app', 'tienda'] AS canales;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q11-struct.webp\" alt=\"Un STRUCT (registro con campos) y un ARRAY en una sola fila\" loading=\"lazy\"><figcaption>Un STRUCT (registro con campos) y un ARRAY en una sola fila</figcaption></figure>\n\n\n<p>Un campo de un STRUCT se lee con punto: <code>sucursal.pais</code>.</p>\n<h2>Paso 4 — ¿Por qué anidar?</h2>\n<p>En BigQuery, un pedido con sus líneas como <code>ARRAY&lt;STRUCT&lt;producto_id, cantidad, precio&gt;&gt;</code> dentro de la misma fila evita el JOIN entre pedidos y detalle, que en tablas de miles de millones de filas es lo más caro. Es el modelo que usa, por ejemplo, la exportación de Google Analytics 4.</p>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Perder filas con <code>UNNEST</code>.</strong> <code>CROSS JOIN UNNEST(lista)</code> descarta las filas cuya lista está vacía; si las necesitas, usa <code>LEFT JOIN UNNEST(lista)</code>.</li>\n<li><strong>Creer que la vista ahorra.</strong> La vista guarda la consulta, no el resultado: cada uso vuelve a leer (y cobrar) las tablas de origen.</li>\n<li><strong>Leer un STRUCT con corchetes.</strong> Los campos se leen con punto (<code>sucursal.pais</code>); los corchetes son para posiciones de un ARRAY (<code>lista[OFFSET(0)]</code>).</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Creaste una vista con arreglos.</li>\n<li>Abriste arreglos con UNNEST.</li>\n<li>Armaste un STRUCT y sabes cuándo anidar.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-vistas-struct-array-y-unnest-ej1","opciones":[{"text":"Sí, una copia","ok":false},{"text":"No: guarda la consulta y la ejecuta cada vez que se usa","ok":true},{"text":"Sí, se actualiza una vez por día","ok":false},{"text":"Solo si es particionada","ok":false}],"enunciado":"<p>¿Una vista guarda datos?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-vistas-struct-array-y-unnest-ej2","opciones":[{"text":"Una lista con los 3 pedidos más recientes de cada grupo","ok":true},{"text":"3 filas por cliente","ok":false},{"text":"El pedido más viejo","ok":false},{"text":"Un error","ok":false}],"enunciado":"<p>¿Qué devuelve ARRAY_AGG(pedido_id ORDER BY fecha_pedido DESC LIMIT 3)?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-vistas-struct-array-y-unnest-ej3","opciones":[{"text":"Convierte la lista en un texto separado por comas","ok":false},{"text":"Abre la lista en filas, una por elemento","ok":true},{"text":"Ordena la lista","ok":false},{"text":"Cuenta los elementos","ok":false}],"enunciado":"<p>¿Qué hace UNNEST(ultimos)?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-vistas-struct-array-y-unnest-ej4","opciones":[{"text":"sucursal[pais]","ok":false},{"text":"sucursal.pais","ok":true},{"text":"pais(sucursal)","ok":false},{"text":"sucursal-&gt;pais","ok":false}],"enunciado":"<p>¿Cómo lees el país de <code>sucursal</code>, un STRUCT con tienda y pais?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true}]},"bigquery-paso-a-paso-proyecto-tabla-de-hechos":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El pedido</div>\n\n<p>Comercial: <em>&quot;Todos los días miramos ventas del último trimestre por país, a veces solo un canal. Que sea rápido y barato.&quot;</em></p>\n</div>\n\n\n<h2>Lo que tienes que lograr</h2>\n<ol>\n<li><code>analitica.hechos_ventas</code> con fecha, canal, país, producto, cantidad e importe de los pedidos <strong>entregados</strong>.</li>\n<li>Partición y clustering según cómo consulta comercial.</li>\n<li>La consulta &quot;ventas web del cuarto trimestre por país&quot; leyendo una fracción chica de la tabla.</li>\n</ol>\n<details><summary>💡 Pista: ¿por qué columnas?</summary>\n\n<p>Comercial <strong>siempre</strong> filtra por fecha (partición) y <strong>a veces</strong> por canal y país (clustering, hasta 4 columnas, en orden de cuánto se filtran).</p>\n</details>\n\n<h2>Cómo se ve terminado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q12-consulta.webp\" alt=\"La estimación de la consulta típica (1), las ventas web del trimestre por país (2) y lo que se leyó - 4 columnas y una fracción de la tabla (3)\" loading=\"lazy\"><figcaption>La estimación de la consulta típica (1), las ventas web del trimestre por país (2) y lo que se leyó - 4 columnas y una fracción de la tabla (3)</figcaption></figure>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Invertir el orden del clustering.</strong> Va primero la columna que más se filtra; si comercial filtra siempre por canal, canal va antes que país.</li>\n<li><strong>Dejar la tabla de hechos como vista.</strong> Cada consulta del día repetiría el JOIN completo y lo cobraría.</li>\n<li><strong>No exigir el filtro de partición.</strong> Sin <code>require_partition_filter</code>, una consulta sin fecha lee la tabla entera.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lista de verificación</h2>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  La tabla está particionada por <code>fecha</code> y con clustering por <code>canal, pais</code>.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  La consulta del trimestre lee una fracción chica (mira &quot;Qué se leyó&quot; en el job).</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Sabes por qué es una tabla y no una vista.</li>\n</ul>\n<details><summary>💡 Solución comentada</summary>\n\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE OR REPLACE TABLE analitica.hechos_ventas\nPARTITION BY fecha\nCLUSTER BY canal, pais\nAS\nSELECT p.fecha_pedido AS fecha, p.canal, c.pais,\n       d.producto_id, d.cantidad,\n       ROUND(d.cantidad * d.precio_unitario, 2) AS importe\nFROM tienda.pedidos AS p\nJOIN tienda.clientes AS c ON c.cliente_id = p.cliente_id\nJOIN tienda.detalle_pedidos AS d ON d.pedido_id = p.pedido_id\nWHERE p.estado = 'entregado';\n\nSELECT pais, ROUND(SUM(importe), 2) AS ventas\nFROM analitica.hechos_ventas\nWHERE fecha BETWEEN '2024-10-01' AND '2024-12-31'\n  AND canal = 'web'\nGROUP BY pais\nORDER BY ventas DESC\nLIMIT 5;</code></pre>\n<p><strong>Por qué una tabla y no una vista:</strong> la vista repetiría los dos JOIN en cada consulta de comercial (y los cobraría). La tabla los paga una vez, al construirse, y queda optimizada para el filtro real. En producción se refresca cada día (nivel 5) o con un MERGE incremental (nivel 4).</p>\n</details>\n\n<h2>Lo que aprendiste en el nivel 3</h2>\n<ul>\n<li>Particiones y clustering.</li>\n<li>Cargas desde archivos.</li>\n<li>Vistas y datos anidados.</li>\n</ul>\n<p>En el nivel 4: MERGE, time travel y SQL analítico.</p>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-tabla-de-hechos-ej1","opciones":[{"text":"Partición por fecha y clustering por canal y país","ok":true},{"text":"Partición por país y clustering por fecha","ok":false},{"text":"Sin partición, con clustering por fecha, canal y país","ok":false},{"text":"Una vista con los JOIN y un LIMIT","ok":false}],"enunciado":"<p>Comercial siempre filtra por fecha y a veces por canal y país. ¿Qué diseño eliges?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-tabla-de-hechos-ej2","opciones":[{"text":"Porque una vista no puede unir más de dos tablas","ok":false},{"text":"Porque la vista repetiría (y cobraría) los JOIN en cada consulta","ok":true},{"text":"Porque la tabla nunca cambia","ok":false},{"text":"Porque la tabla se actualiza sola con cada pedido","ok":false}],"enunciado":"<p>¿Por qué conviene una tabla de hechos y no una vista con los JOIN?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-tabla-de-hechos-ej3","opciones":[{"text":"En el explorador","ok":false},{"text":"En la información del job, &quot;Qué se leyó&quot;","ok":true},{"text":"En Preview","ok":false},{"text":"No se puede ver","ok":false}],"enunciado":"<p>¿Dónde ves qué fracción de la tabla leyó una consulta?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-tabla-de-hechos-ej4","opciones":[{"text":"De la que más se filtra a la que menos","ok":true},{"text":"Alfabético","ok":false},{"text":"De la que tiene más valores distintos a la que menos","ok":false},{"text":"Da igual: BigQuery las reordena solo","ok":false}],"enunciado":"<p>¿En qué orden van las columnas de CLUSTER BY?</p>\n","dificultad":"3 · Intermedio","dificultadLeccion":true}]},"bigquery-paso-a-paso-merge":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Conciliar el inventario</div>\n\n<p>MERGE es conciliar tu planilla de inventario con la lista del proveedor en una sola pasada: lo que llegó cambiado se actualiza, lo nuevo se agrega y lo que el proveedor dice que ya no hay se borra. Sin MERGE serían tres sentencias, y entre una y otra la tabla quedaría a medias.</p>\n</div>\n\n\n<h2>Paso 1 — El MERGE</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE OR REPLACE TABLE analitica.stock_tiendas AS\nSELECT producto_id, stock FROM tienda.productos WHERE producto_id &lt;= 5;\n\nMERGE analitica.stock_tiendas AS t\nUSING (SELECT 1 AS producto_id, 0 AS stock\n       UNION ALL SELECT 2, 99\n       UNION ALL SELECT 500, 12) AS s\nON t.producto_id = s.producto_id\nWHEN MATCHED AND s.stock = 0 THEN DELETE\nWHEN MATCHED THEN UPDATE SET stock = s.stock\nWHEN NOT MATCHED THEN INSERT (producto_id, stock) VALUES (s.producto_id, s.stock);</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q13-merge.webp\" alt=\"El MERGE (1) - &quot;This statement modified 3 rows&quot;: un borrado, una actualización y una inserción (2)\" loading=\"lazy\"><figcaption>El MERGE (1) - &quot;This statement modified 3 rows&quot;: un borrado, una actualización y una inserción (2)</figcaption></figure>\n\n\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q13-resultado.webp\" alt=\"El stock - el producto 1 ya no está, el 2 tiene 99 y el 500 es nuevo\" loading=\"lazy\"><figcaption>El stock - el producto 1 ya no está, el 2 tiene 99 y el 500 es nuevo</figcaption></figure>\n\n\n<p>Para cada fila de la fuente se aplica <strong>la primera cláusula WHEN que se cumple</strong>: el producto 1 llega con stock 0 y entra por el <code>DELETE</code>, aunque también cumpliría el <code>UPDATE</code>.</p>\n<h2>Paso 2 — Las cláusulas de BigQuery</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Cláusula</th>\n<th>Se aplica a</th>\n</tr>\n</thead><tbody><tr>\n<td><code>WHEN MATCHED [AND …]</code></td>\n<td>Filas que están en el destino y en la fuente</td>\n</tr>\n<tr>\n<td><code>WHEN NOT MATCHED [BY TARGET] [AND …]</code></td>\n<td>Filas de la fuente que no están en el destino</td>\n</tr>\n<tr>\n<td><code>WHEN NOT MATCHED BY SOURCE [AND …]</code></td>\n<td>Filas del destino que no vinieron en la fuente (por ejemplo, productos discontinuados)</td>\n</tr>\n<tr>\n<td><code>INSERT ROW</code></td>\n<td>Inserta la fila de la fuente completa, sin listar columnas</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 3 — DML con WHERE obligatorio</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">UPDATE analitica.stock_tiendas SET stock = 0;              -- error: UPDATE must have a WHERE clause\nUPDATE analitica.stock_tiendas SET stock = 0 WHERE TRUE;   -- explícito: todas las filas</code></pre>\n<p>BigQuery obliga a escribir <code>WHERE</code> en <code>UPDATE</code> y <code>DELETE</code>: un recordatorio de que vas a tocar filas. Y los DML se cobran por los bytes que leen de la tabla, como cualquier consulta.</p>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">💡 MERGE para cargas</div>\n\n<p>Un MERGE bien escrito es <strong>idempotente</strong>: correrlo dos veces con los mismos datos deja el mismo resultado. Es la forma recomendada de aplicar cargas incrementales.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Poner las cláusulas en cualquier orden.</strong> Gana la primera que se cumple: la condición más específica (por ejemplo, stock en cero → borrar) va antes que la general.</li>\n<li><strong>Fuente con claves repetidas.</strong> Si dos filas de la fuente coinciden con la misma fila del destino, el MERGE falla; deduplica la fuente antes.</li>\n<li><strong><code>WHEN NOT MATCHED BY SOURCE THEN DELETE</code> con un archivo parcial.</strong> Borra todo lo que no vino en el archivo; úsalo solo si la fuente trae la foto completa.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Escribiste un MERGE con borrado, actualización e inserción.</li>\n<li>Conoces las cláusulas BY TARGET, BY SOURCE e INSERT ROW.</li>\n<li>Sabes por qué los DML exigen WHERE.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-merge-ej1","opciones":[{"text":"Se borra: gana la primera cláusula que se cumple","ok":true},{"text":"Se actualiza a 0","ok":false},{"text":"Se borra y se actualiza","ok":false},{"text":"Da error","ok":false}],"enunciado":"<p>El producto 1 llega con stock 0 y hay dos cláusulas MATCHED (DELETE si stock = 0, luego UPDATE). ¿Qué pasa?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-merge-ej2","opciones":[{"text":"Inserta las filas nuevas","ok":false},{"text":"Actúa sobre las filas del destino que no vinieron en la fuente","ok":true},{"text":"Borra las filas de la fuente después de leerlas","ok":false},{"text":"Actúa sobre las filas de la fuente que no están en el destino","ok":false}],"enunciado":"<p>¿Qué hace WHEN NOT MATCHED BY SOURCE?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-merge-ej3","opciones":[{"text":"Inserta la fila completa de la fuente sin listar columnas","ok":true},{"text":"Inserta una fila vacía","ok":false},{"text":"Inserta solo la primera columna","ok":false},{"text":"Inserta la fila y luego actualiza las que coinciden","ok":false}],"enunciado":"<p>¿Qué hace INSERT ROW?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-merge-ej4","opciones":[{"text":"Borra todo","ok":false},{"text":"Da error: DELETE must have a WHERE clause","ok":true},{"text":"Pide confirmación en la consola","ok":false},{"text":"Borra solo las filas de la última carga","ok":false}],"enunciado":"<p>¿Qué pasa con <code>DELETE FROM tabla</code> sin WHERE en BigQuery?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true}]},"bigquery-paso-a-paso-time-travel":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 El grabador de la tabla</div>\n\n<p>Time travel es como un grabador que guarda los últimos 7 días de la tabla: puedes rebobinar y mirarla como estaba hace un minuto o hace tres días. Pasado ese plazo, la grabación se pierde; para guardar un momento por más tiempo están los snapshots.</p>\n</div>\n\n\n<h2>Paso 1 — El error</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">-- en BigQuery el WHERE es obligatorio, pero WHERE TRUE borra todo\nDELETE FROM analitica.ventas_por_canal WHERE TRUE;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q14-delete.webp\" alt=\"El DELETE con WHERE TRUE (1) - 4 filas borradas (2)\" loading=\"lazy\"><figcaption>El DELETE con WHERE TRUE (1) - 4 filas borradas (2)</figcaption></figure>\n\n\n<h2>Paso 2 — Mirar el pasado</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT *\nFROM analitica.ventas_por_canal\n  FOR SYSTEM_TIME AS OF TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 1 MINUTE);</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q14-system-time.webp\" alt=\"FOR SYSTEM_TIME AS OF (1) - la tabla como estaba hace un minuto, con sus 4 canales (2)\" loading=\"lazy\"><figcaption>FOR SYSTEM_TIME AS OF (1) - la tabla como estaba hace un minuto, con sus 4 canales (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Forma</th>\n<th>Qué devuelve</th>\n</tr>\n</thead><tbody><tr>\n<td><code>FOR SYSTEM_TIME AS OF TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 1 HOUR)</code></td>\n<td>La tabla hace una hora</td>\n</tr>\n<tr>\n<td><code>FOR SYSTEM_TIME AS OF &#39;2026-11-15 18:00:00+00&#39;</code></td>\n<td>La tabla en ese instante</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 3 — Restaurar</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">INSERT INTO analitica.ventas_por_canal\nSELECT *\nFROM analitica.ventas_por_canal\n  FOR SYSTEM_TIME AS OF TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 1 MINUTE);</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q14-restaurado.webp\" alt=\"El INSERT desde el pasado (1) y la tabla con sus 4 canales de vuelta (2)\" loading=\"lazy\"><figcaption>El INSERT desde el pasado (1) y la tabla con sus 4 canales de vuelta (2)</figcaption></figure>\n\n\n<p>Si la tabla entera se borró (<code>DROP TABLE</code>), también se recupera dentro de la ventana, con <code>bq cp</code> usando el decorador de tiempo o desde la consola.</p>\n<h2>Paso 4 — Ventanas y copias</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Concepto</th>\n<th>Duración</th>\n<th>Para</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Time travel</strong></td>\n<td>7 días por defecto (configurable de 2 a 7 por dataset)</td>\n<td>Consultar y recuperar con SQL</td>\n</tr>\n<tr>\n<td><strong>Fail-safe</strong></td>\n<td>7 días más, solo vía soporte de Google</td>\n<td>Desastres</td>\n</tr>\n<tr>\n<td><strong>Snapshot de tabla</strong></td>\n<td>Lo que decidas</td>\n<td>Copia de solo lectura en un momento: <code>CREATE SNAPSHOT TABLE pedidos_snap CLONE tienda.pedidos;</code></td>\n</tr>\n<tr>\n<td><strong>Clon de tabla</strong></td>\n<td>Lo que decidas</td>\n<td>Copia que se puede modificar; solo paga lo que cambia: <code>CREATE TABLE pedidos_prueba CLONE tienda.pedidos;</code></td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Contar con time travel para siempre.</strong> La ventana es de 7 días (o menos si se configuró); después solo queda el fail-safe, que no puedes consultar tú.</li>\n<li><strong>Restaurar sin una copia previa.</strong> Antes de pisar la tabla, guarda el estado actual (un snapshot o un clon) por si la restauración también sale mal.</li>\n<li><strong>Usar time travel como backup.</strong> No reemplaza los snapshots programados antes de cargas grandes y riesgosas.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Consultaste una tabla en el pasado.</li>\n<li>Restauraste un borrado.</li>\n<li>Conoces las ventanas y las copias.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-time-travel-ej1","opciones":[{"text":"<code>FOR SYSTEM_TIME AS OF TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 1 HOUR)</code>","ok":true},{"text":"<code>AT(OFFSET =&gt; -3600)</code>","ok":false},{"text":"<code>SELECT * FROM tabla_ayer</code>","ok":false},{"text":"Con <code>SELECT * FROM tabla@-3600000</code>","ok":false}],"enunciado":"<p>¿Cómo consultas la tabla como estaba hace una hora?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-time-travel-ej2","opciones":[{"text":"1","ok":false},{"text":"7","ok":true},{"text":"30","ok":false},{"text":"90","ok":false}],"enunciado":"<p>¿Cuántos días dura time travel por defecto en BigQuery?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-time-travel-ej3","opciones":[{"text":"Una vista que apunta a la tabla original","ok":false},{"text":"Una copia de solo lectura de la tabla en un momento","ok":true},{"text":"Una vista","ok":false},{"text":"Una copia que se actualiza sola con los cambios","ok":false}],"enunciado":"<p>¿Qué es un snapshot de tabla?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-time-travel-ej4","opciones":[{"text":"El clon se puede modificar; el snapshot es de solo lectura","ok":true},{"text":"No hay diferencia","ok":false},{"text":"El clon es más caro siempre","ok":false},{"text":"El snapshot se puede modificar","ok":false}],"enunciado":"<p>¿En qué se diferencia un clon de un snapshot?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true}]},"bigquery-paso-a-paso-sql-analitico":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Numerar y quedarse con el primero</div>\n\n<p><code>QUALIFY</code> es al resultado de una función de ventana lo que <code>HAVING</code> es al de un <code>GROUP BY</code>: primero numeras los pedidos de cada cliente del más reciente al más viejo y después te quedas con el número 1, sin subconsultas.</p>\n</div>\n\n\n<h2>Paso 1 — QUALIFY</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT cliente_id, pedido_id, fecha_pedido, canal\nFROM tienda.pedidos\nWHERE fecha_pedido &gt;= '2024-01-01'\nQUALIFY ROW_NUMBER() OVER (PARTITION BY cliente_id ORDER BY fecha_pedido DESC, pedido_id DESC) = 1\nORDER BY cliente_id\nLIMIT 10;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q15-qualify.webp\" alt=\"QUALIFY con ROW_NUMBER (1) - el último pedido de cada cliente en 2024 (2)\" loading=\"lazy\"><figcaption>QUALIFY con ROW_NUMBER (1) - el último pedido de cada cliente en 2024 (2)</figcaption></figure>\n\n\n<h2>Paso 2 — Ventanas y porcentajes</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">WITH mensual AS (\n  SELECT DATE_TRUNC(fecha_pedido, MONTH) AS mes,\n         COUNT(*) AS pedidos,\n         COUNTIF(canal = 'web') AS web\n  FROM tienda.pedidos\n  WHERE fecha_pedido &gt;= '2024-01-01'\n  GROUP BY mes\n)\nSELECT mes, pedidos,\n       pedidos - LAG(pedidos) OVER (ORDER BY mes) AS variacion,\n       ROUND(SAFE_DIVIDE(web, pedidos) * 100, 1) AS pct_web\nFROM mensual\nORDER BY mes;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q15-ventana.webp\" alt=\"La CTE con LAG y SAFE_DIVIDE (1) - pedidos por mes, variación contra el mes anterior y porcentaje web (2)\" loading=\"lazy\"><figcaption>La CTE con LAG y SAFE_DIVIDE (1) - pedidos por mes, variación contra el mes anterior y porcentaje web (2)</figcaption></figure>\n\n\n<h2>Paso 3 — Funciones que más se usan</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Función</th>\n<th>Para</th>\n</tr>\n</thead><tbody><tr>\n<td><code>DATE_TRUNC(f, MONTH)</code>, <code>DATE_DIFF(a, b, DAY)</code>, <code>DATE_ADD(f, INTERVAL 7 DAY)</code></td>\n<td>Fechas</td>\n</tr>\n<tr>\n<td><code>FORMAT_DATE(&#39;%Y-%m&#39;, f)</code>, <code>PARSE_DATE(&#39;%d/%m/%Y&#39;, txt)</code></td>\n<td>Fechas a texto y texto a fechas</td>\n</tr>\n<tr>\n<td><code>COUNTIF(cond)</code>, <code>LOGICAL_OR(cond)</code></td>\n<td>Contar o comprobar condiciones</td>\n</tr>\n<tr>\n<td><code>SAFE_DIVIDE(a, b)</code>, <code>SAFE_CAST(x AS INT64)</code></td>\n<td>Devuelven <code>NULL</code> en lugar de fallar</td>\n</tr>\n<tr>\n<td><code>APPROX_COUNT_DISTINCT(x)</code></td>\n<td>Distintos aproximados, mucho más baratos en tablas enormes</td>\n</tr>\n<tr>\n<td><code>SELECT * EXCEPT(col)</code></td>\n<td>Todas las columnas menos algunas</td>\n</tr>\n<tr>\n<td><code>REGEXP_EXTRACT(txt, r&#39;…&#39;)</code></td>\n<td>Extraer con expresiones regulares</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Filtrar una ventana en el <code>WHERE</code>.</strong> El <code>WHERE</code> se evalúa antes que las ventanas y da error; el filtro va en <code>QUALIFY</code>.</li>\n<li><strong>Dividir con <code>/</code>.</strong> Si el divisor puede ser 0, la consulta falla; <code>SAFE_DIVIDE</code> devuelve NULL.</li>\n<li><strong><code>LAG</code> sin <code>ORDER BY</code>.</strong> Sin orden, &quot;la fila anterior&quot; no está definida y el resultado no tiene sentido.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Filtraste con QUALIFY.</li>\n<li>Calculaste variaciones y porcentajes.</li>\n<li>Conoces las funciones clave de GoogleSQL.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-sql-analitico-ej1","opciones":[{"text":"Filas según el resultado de una función de ventana","ok":true},{"text":"Grupos después de GROUP BY","ok":false},{"text":"Columnas","ok":false},{"text":"Particiones","ok":false}],"enunciado":"<p>¿Qué filtra QUALIFY?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-sql-analitico-ej2","opciones":[{"text":"Un error de división por cero","ok":false},{"text":"0","ok":false},{"text":"NULL","ok":true},{"text":"Infinito","ok":false}],"enunciado":"<p>¿Qué devuelve SAFE_DIVIDE(1, 0)?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-sql-analitico-ej3","opciones":[{"text":"COUNT(web) / 100","ok":false},{"text":"SAFE_DIVIDE(COUNTIF(canal = &#39;web&#39;), COUNT(*)) * 100, agrupando por mes","ok":true},{"text":"SUM(canal)","ok":false},{"text":"AVG(canal = &#39;web&#39;) sobre toda la tabla, sin agrupar por mes","ok":false}],"enunciado":"<p>¿Cómo calculas el porcentaje de pedidos web por mes?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-sql-analitico-ej4","opciones":[{"text":"Cuando hace falta el número exacto para facturar","ok":false},{"text":"Cuando un valor aproximado alcanza y la tabla es enorme: es mucho más barato","ok":true},{"text":"Para contar exacto","ok":false},{"text":"Solo en tablas chicas","ok":false}],"enunciado":"<p>¿Cuándo conviene APPROX_COUNT_DISTINCT?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true}]},"bigquery-paso-a-paso-proyecto-stock-al-dia":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El pedido</div>\n\n<p>Operaciones: <em>&quot;Les mandamos el stock de hoy: el producto 2 sigue en 99, el 3 bajó a 7 y el 500 sigue en 12. Que la tabla quede al día sin tocar lo que no cambió.&quot;</em></p>\n</div>\n\n\n<h2>Lo que tienes que lograr</h2>\n<ol>\n<li>Un MERGE sobre <code>analitica.stock_tiendas</code> que actualice <strong>solo</strong> si el stock cambió e inserte lo que no existe.</li>\n<li>Correrlo dos veces: la segunda no debe modificar ninguna fila.</li>\n<li>Una línea con el procedimiento para recuperar la tabla si el MERGE sale mal.</li>\n</ol>\n<h2>Cómo se ve terminado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q16-stock.webp\" alt=\"El MERGE con AND t.stock &lt;&gt; s.stock e INSERT ROW (1) y el stock final - el 3 en 7 y el resto sin cambios (2)\" loading=\"lazy\"><figcaption>El MERGE con AND t.stock &lt;&gt; s.stock e INSERT ROW (1) y el stock final - el 3 en 7 y el resto sin cambios (2)</figcaption></figure>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Actualizar aunque nada haya cambiado.</strong> Sin <code>AND t.stock &lt;&gt; s.stock</code>, el MERGE reescribe todas las filas que coinciden en cada corrida.</li>\n<li><strong>No probar la idempotencia.</strong> Correrlo dos veces seguidas es la prueba: la segunda corrida no debe modificar nada.</li>\n<li><strong>No tener un plan de recuperación.</strong> Anota antes de correr cómo volverías atrás (time travel o snapshot) y comprueba que funciona.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lista de verificación</h2>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  El producto 3 quedó en 7.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  El 2 y el 500 no se reescribieron.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  La segunda ejecución dice que modificó 0 filas.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Tienes el procedimiento de recuperación.</li>\n</ul>\n<details><summary>💡 Solución comentada</summary>\n\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">MERGE analitica.stock_tiendas AS t\nUSING (SELECT 2 AS producto_id, 99 AS stock\n       UNION ALL SELECT 3, 7\n       UNION ALL SELECT 500, 12) AS s\nON t.producto_id = s.producto_id\nWHEN MATCHED AND t.stock &lt;&gt; s.stock THEN UPDATE SET stock = s.stock\nWHEN NOT MATCHED BY TARGET THEN INSERT ROW;</code></pre>\n<ul>\n<li><code>AND t.stock &lt;&gt; s.stock</code> evita reescribir filas iguales: menos filas modificadas, historial más limpio y, en tablas particionadas, menos particiones tocadas.</li>\n<li><code>INSERT ROW</code> sirve porque la fuente tiene las mismas columnas que el destino.</li>\n<li><strong>Recuperación:</strong> <code>CREATE OR REPLACE TABLE analitica.stock_tiendas AS SELECT * FROM analitica.stock_tiendas FOR SYSTEM_TIME AS OF TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 1 HOUR);</code> (dentro de los 7 días de time travel). Mejor aún: un snapshot antes de cada carga grande.</details></li>\n</ul>\n<h2>Lo que aprendiste en el nivel 4</h2>\n<ul>\n<li>MERGE con todas sus cláusulas.</li>\n<li>Time travel, snapshots y clones.</li>\n<li>QUALIFY, ventanas y funciones de GoogleSQL.</li>\n</ul>\n<p>En el nivel 5: INFORMATION_SCHEMA, automatización, acceso y costos.</p>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-stock-al-dia-ej1","opciones":[{"text":"Para actualizar solo los productos cuyo stock cambió","ok":true},{"text":"Para borrar los iguales","ok":false},{"text":"Para insertar duplicados","ok":false},{"text":"Nada","ok":false}],"enunciado":"<p>¿Para qué sirve <code>WHEN MATCHED AND t.stock &lt;&gt; s.stock</code>?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-stock-al-dia-ej2","opciones":[{"text":"Duplicar filas","ok":false},{"text":"No modificar ninguna fila","ok":true},{"text":"Borrar la tabla","ok":false},{"text":"Dar error","ok":false}],"enunciado":"<p>Corres el MERGE dos veces con los mismos datos. ¿Qué debe pasar la segunda vez?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-stock-al-dia-ej3","opciones":[{"text":"UNDROP","ok":false},{"text":"Con FOR SYSTEM_TIME AS OF hace una hora (dentro de los 7 días)","ok":true},{"text":"Desde Preview","ok":false},{"text":"Con un ROLLBACK de la sesión, aunque ya terminó","ok":false}],"enunciado":"<p>¿Cómo recuperas la tabla como estaba hace una hora?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-stock-al-dia-ej4","opciones":[{"text":"Cuando la fuente tiene las mismas columnas que el destino","ok":true},{"text":"Siempre, aunque falten columnas","ok":false},{"text":"Solo en UPDATE","ok":false},{"text":"Cuando la fuente tiene más columnas que el destino","ok":false}],"enunciado":"<p>¿Cuándo sirve INSERT ROW?</p>\n","dificultad":"4 · Intermedio-avanzado","dificultadLeccion":true}]},"bigquery-paso-a-paso-information-schema":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 El tablero del auto</div>\n\n<p>Para saber cómo va el auto no abres el motor: miras el tablero. <code>INFORMATION_SCHEMA</code> es el tablero del proyecto en forma de tablas: qué jobs corrieron, cuánto leyeron, qué tablas y columnas existen. Y como son tablas, se pueden consultar y graficar.</p>\n</div>\n\n\n<h2>Paso 1 — Quién gasta</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT job_type,\n       COUNT(*) AS jobs,\n       SUM(total_bytes_processed) AS bytes_procesados,\n       SUM(total_bytes_billed) AS bytes_facturados,\n       COUNTIF(cache_hit) AS desde_cache\nFROM `region-us`.INFORMATION_SCHEMA.JOBS\nGROUP BY job_type;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q17-jobs.webp\" alt=\"INFORMATION_SCHEMA.JOBS (1) - jobs, bytes procesados y facturados y cuántos salieron de la caché, por tipo (2)\" loading=\"lazy\"><figcaption>INFORMATION_SCHEMA.JOBS (1) - jobs, bytes procesados y facturados y cuántos salieron de la caché, por tipo (2)</figcaption></figure>\n\n\n<p>Los jobs se guardan <strong>por región</strong>: por eso la vista lleva el prefijo <code>`region-us`</code> (o <code>region-eu</code>, etc.).</p>\n<h2>Paso 2 — Las consultas más caras</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT query, total_bytes_billed\nFROM `region-us`.INFORMATION_SCHEMA.JOBS\nWHERE job_type = 'QUERY'\nORDER BY total_bytes_billed DESC\nLIMIT 5;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q17-caras.webp\" alt=\"Las 5 consultas que más bytes facturaron\" loading=\"lazy\"><figcaption>Las 5 consultas que más bytes facturaron</figcaption></figure>\n\n\n<p>En un proyecto real se agrega <code>WHERE creation_time &gt;= TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 7 DAY)</code> y <code>user_email</code> para saber de quién es cada consulta.</p>\n<h2>Paso 3 — Tablas y columnas</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT column_name, data_type, is_nullable\nFROM tienda.INFORMATION_SCHEMA.COLUMNS\nWHERE table_name = 'pedidos';</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q17-columnas.webp\" alt=\"Las columnas de pedidos con su tipo\" loading=\"lazy\"><figcaption>Las columnas de pedidos con su tipo</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Vista</th>\n<th>Qué tiene</th>\n</tr>\n</thead><tbody><tr>\n<td><code>dataset.INFORMATION_SCHEMA.TABLES</code></td>\n<td>Tablas y vistas del dataset</td>\n</tr>\n<tr>\n<td><code>dataset.INFORMATION_SCHEMA.COLUMNS</code></td>\n<td>Columnas, tipos y nulos</td>\n</tr>\n<tr>\n<td><code>region-us.INFORMATION_SCHEMA.JOBS</code></td>\n<td>Todos los jobs del proyecto (requiere permiso de administrador de jobs)</td>\n</tr>\n<tr>\n<td><code>region-us.INFORMATION_SCHEMA.JOBS_BY_USER</code></td>\n<td>Solo tus jobs</td>\n</tr>\n<tr>\n<td><code>region-us.INFORMATION_SCHEMA.TABLE_STORAGE</code></td>\n<td>Almacenamiento por tabla (activo y de largo plazo)</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-nota\"><div class=\"callout-title\">📝 Costo de INFORMATION_SCHEMA</div>\n\n<p>Consultar estas vistas también es un job y se factura (con el mínimo de 10 MB). Para un tablero diario de costos, guarda el resultado en una tabla una vez al día.</p>\n</div>\n\n\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Olvidar la región.</strong> Los jobs se guardan por región: es <code>`region-us`.INFORMATION_SCHEMA.JOBS</code>, no <code>INFORMATION_SCHEMA.JOBS</code> a secas.</li>\n<li><strong>Consultar JOBS sin filtrar por fecha.</strong> Leer todo el historial también procesa bytes; filtra por <code>creation_time</code>.</li>\n<li><strong>Usar JOBS_BY_USER para un informe del equipo.</strong> Solo trae tus jobs; para todo el proyecto es JOBS (y requiere permisos).</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Mediste el gasto por tipo de job con SQL.</li>\n<li>Encontraste las consultas más caras.</li>\n<li>Listaste tablas y columnas.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-information-schema-ej1","opciones":[{"text":"Porque los jobs se guardan por región","ok":true},{"text":"Porque es el nombre del proyecto","ok":false},{"text":"Porque los jobs se guardan en un dataset llamado region-us","ok":false},{"text":"Porque solo existe en Estados Unidos","ok":false}],"enunciado":"<p>¿Por qué INFORMATION_SCHEMA.JOBS lleva el prefijo <code>region-us</code>?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-information-schema-ej2","opciones":[{"text":"SELECT * FROM jobs LIMIT 1","ok":false},{"text":"Ordenando INFORMATION_SCHEMA.JOBS por total_bytes_billed DESC","ok":true},{"text":"En Preview","ok":false},{"text":"En la página de costos, que no se puede consultar con SQL","ok":false}],"enunciado":"<p>¿Cómo encuentras la consulta que más facturó?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-information-schema-ej3","opciones":[{"text":"dataset.INFORMATION_SCHEMA.TABLES","ok":false},{"text":"dataset.INFORMATION_SCHEMA.COLUMNS","ok":true},{"text":"region-us.INFORMATION_SCHEMA.JOBS","ok":false},{"text":"SHOW COLUMNS","ok":false}],"enunciado":"<p>¿Qué vista lista las columnas de las tablas de un dataset?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-information-schema-ej4","opciones":[{"text":"Ninguna","ok":false},{"text":"JOBS tiene los jobs de todo el proyecto; JOBS_BY_USER solo los tuyos","ok":true},{"text":"JOBS_BY_USER es más caro","ok":false},{"text":"JOBS solo tiene cargas","ok":false}],"enunciado":"<p>¿Qué diferencia hay entre JOBS y JOBS_BY_USER?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true}]},"bigquery-paso-a-paso-automatizar":{"html":"<div class=\"callout callout-tip\"><div class=\"callout-title\">💡 Practícalo mientras lees</div>\n\n<p>En el <a href=\"#/bigquery\">BigQuery de práctica</a> funcionan las tres cosas de esta lección: <strong>Scheduled queries</strong> (con horario UTC, <code>@run_date</code>, destino y backfill), <strong>Data transfers</strong> (desde tus buckets de S3 o Cloud Storage) y <strong>Dataform</strong> (SQLX con <code>ref()</code>, incrementales y assertions).</p>\n</div>\n\n\n<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Despertador, receta y jefe de cocina</div>\n\n<p>Una scheduled query es un despertador: corre un SQL a la hora fijada. Dataform es la receta escrita, con el orden de los pasos y controles de calidad. Un orquestador como Airflow es el jefe de cocina que coordina varias cocinas: espera un archivo, corre Dataflow, después BigQuery y avisa si algo falla.</p>\n</div>\n\n\n<h2>Paso 1 — Scheduled queries</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q18-programadas.webp\" alt=\"Scheduled queries - el detalle de una consulta programada: horario en UTC, destino, cuenta de servicio y el historial de corridas\" loading=\"lazy\"><figcaption>Scheduled queries - el detalle de una consulta programada: horario en UTC, destino, cuenta de servicio y el historial de corridas</figcaption></figure>\n\n\n<p>En la consola, desde el editor: <strong>Schedule</strong> → nombre, frecuencia (por ejemplo, todos los días a las 06:00), dataset y tabla de destino y si <strong>sobrescribe</strong> o <strong>agrega</strong>. Usa los parámetros de la ejecución:</p>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">-- se ejecuta cada día y carga solo el día anterior en la partición correspondiente\nSELECT fecha_pedido AS fecha, canal, COUNT(*) AS pedidos\nFROM tienda.pedidos\nWHERE fecha_pedido = DATE_SUB(@run_date, INTERVAL 1 DAY)\nGROUP BY fecha, canal;</code></pre>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Parámetro</th>\n<th>Qué es</th>\n</tr>\n</thead><tbody><tr>\n<td><code>@run_date</code></td>\n<td>La fecha de la ejecución programada</td>\n</tr>\n<tr>\n<td><code>@run_time</code></td>\n<td>El instante de la ejecución</td>\n</tr>\n<tr>\n<td>Destino <code>tabla$${run_date}</code></td>\n<td>Escribe en la partición de ese día</td>\n</tr>\n</tbody></table></div>\n<p>Tres detalles que en la práctica se ven igual que en la consola real:</p>\n<ul>\n<li>El horario se escribe en inglés y está en <strong>UTC</strong>: <code>every day 09:00</code> es a las 6:00 de Buenos Aires. Las opciones válidas son del estilo <code>every 24 hours</code>, <code>every day 06:00</code>, <code>every monday 09:00</code> o <code>every mon,wed,fri 07:30</code>, con un mínimo de 15 minutos.</li>\n<li>La consulta corre con una <strong>cuenta de servicio</strong>, no con tu usuario: esa cuenta necesita permisos sobre el dataset de destino.</li>\n<li><strong>Schedule backfill</strong> corre la consulta una vez por cada día de un rango, con <code>@run_date</code> igual a ese día. Es la forma de reprocesar días sin tocar el SQL.</li>\n</ul>\n<h2>Paso 2 — Dataform</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q18-dataform.webp\" alt=\"Dataform - los archivos SQLX, la consulta compilada y el grafo de dependencias\" loading=\"lazy\"><figcaption>Dataform - los archivos SQLX, la consulta compilada y el grafo de dependencias</figcaption></figure>\n\n\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">-- definitions/hechos_ventas.sqlx\nconfig {\n  type: &quot;incremental&quot;,\n  bigquery: { partitionBy: &quot;fecha&quot;, clusterBy: [&quot;canal&quot;, &quot;pais&quot;] },\n  assertions: { nonNull: [&quot;fecha&quot;, &quot;canal&quot;] }\n}\nSELECT p.fecha_pedido AS fecha, p.canal, c.pais, d.cantidad\nFROM ${ref(&quot;pedidos&quot;)} AS p\nJOIN ${ref(&quot;clientes&quot;)} AS c USING (cliente_id)\nJOIN ${ref(&quot;detalle_pedidos&quot;)} AS d USING (pedido_id)\n${ when(incremental(), `WHERE p.fecha_pedido &gt; (SELECT MAX(fecha) FROM ${self()})`) }</code></pre>\n<p><code>${ref(...)}</code> arma el grafo de dependencias, las <strong>assertions</strong> son pruebas de calidad y todo vive en Git: la misma idea que <a href=\"#/m/dbt\">dbt</a>, pero integrado en BigQuery.</p>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Tipo (<code>config { type: … }</code>)</th>\n<th>Qué crea</th>\n<th>Cuándo</th>\n</tr>\n</thead><tbody><tr>\n<td><code>declaration</code></td>\n<td>Nada: declara una tabla que ya existe para poder usar <code>ref()</code></td>\n<td>Las fuentes (lo que cargan otros)</td>\n</tr>\n<tr>\n<td><code>view</code></td>\n<td>Una vista</td>\n<td>Staging liviano</td>\n</tr>\n<tr>\n<td><code>table</code></td>\n<td>Una tabla que se recrea completa en cada ejecución</td>\n<td>Marts chicos o medianos</td>\n</tr>\n<tr>\n<td><code>incremental</code></td>\n<td>Una tabla que la primera vez se crea y después solo agrega lo nuevo (<code>when(incremental(), …)</code>)</td>\n<td>Hechos grandes que crecen todos los días</td>\n</tr>\n<tr>\n<td><code>assertion</code></td>\n<td>Una consulta que tiene que devolver <strong>cero</strong> filas</td>\n<td>Controles de calidad que frenan lo que depende de ellos</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-practica\" data-app=\"bigquery\" data-motor=\"\" data-titulo=\"Dataform de punta a punta\"><div class=\"callout-title\">🛠️ Practícalo en la herramienta: Dataform de punta a punta</div>\n\n<ol>\n<li>Abre <strong>Dataform</strong>: el repositorio de práctica ya trae dos fuentes declaradas, una vista de staging, una tabla, una incremental y una assertion.</li>\n<li>Mira el <strong>grafo compilado</strong> y la <strong>consulta compilada</strong> de <code>ventas_diarias</code>: <code>${ref(&quot;stg_pedidos&quot;)}</code> se convirtió en <code>`dataform.stg_pedidos`</code>.</li>\n<li><strong>Start execution</strong>: se crean la vista, la tabla y la incremental, y corren las assertions (las de <code>nonNull</code> y <code>uniqueKey</code> salen del config).</li>\n<li>Vuelve a ejecutar y mira la consulta incremental: agrega solo las filas con fecha posterior al máximo, sin duplicar.</li>\n<li>Rompe algo a propósito: en <code>ventas_positivas.sqlx</code> cambia <code>ventas &lt; 0</code> por <code>ventas &gt; 0</code>. La assertion falla y lo que depende de ella se marca como SKIPPED.</li>\n</ol>\n</div>\n\n\n<h2>Paso 3 — ¿Qué uso?</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Si…</th>\n<th>Conviene</th>\n</tr>\n</thead><tbody><tr>\n<td>Es una consulta suelta que corre a horario</td>\n<td>Scheduled query</td>\n</tr>\n<tr>\n<td>Son varias transformaciones SQL con dependencias y pruebas</td>\n<td>Dataform (o dbt)</td>\n</tr>\n<tr>\n<td>El flujo mezcla BigQuery con APIs, archivos, otros sistemas y avisos</td>\n<td>Un orquestador: <a href=\"#/m/airflow-paso-a-paso\">Airflow</a> o Cloud Composer (Airflow administrado)</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Encadenar consultas programadas por horario</strong> (&quot;esta a las 6, la otra a las 6:30&quot;). Si la primera se demora, la segunda lee datos incompletos; las dependencias van en Dataform o en un orquestador.</li>\n<li><strong>Ignorar <code>@run_date</code>.</strong> Con <code>CURRENT_DATE()</code>, un reproceso de días anteriores calcula siempre el día de hoy.</li>\n<li><strong>Dejar el SQL en una pestaña de la consola.</strong> Sin control de versiones, nadie sabe qué cambió ni cuándo.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Sabes programar una consulta con parámetros de fecha.</li>\n<li>Conoces Dataform.</li>\n<li>Sabes elegir la herramienta de automatización.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-automatizar-ej1","opciones":[{"text":"Ejecuta un SQL a horario y escribe el resultado en una tabla","ok":true},{"text":"Borra tablas viejas","ok":false},{"text":"Carga archivos de S3","ok":false},{"text":"Recalcula las vistas una vez por día","ok":false}],"enunciado":"<p>¿Qué hace una scheduled query?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-automatizar-ej2","opciones":[{"text":"Para fijar a qué hora se ejecuta","ok":false},{"text":"Para usar la fecha de la ejecución y procesar el día que corresponde","ok":true},{"text":"Para cambiar de región","ok":false},{"text":"Para pausar la consulta","ok":false}],"enunciado":"<p>¿Para qué sirve @run_date en una scheduled query?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-automatizar-ej3","opciones":[{"text":"Ambos definen transformaciones SQL con dependencias, pruebas y Git","ok":true},{"text":"Ambos son bases de datos","ok":false},{"text":"Ambos cargan archivos","ok":false},{"text":"Ambos programan consultas sueltas sin dependencias","ok":false}],"enunciado":"<p>¿En qué se parece Dataform a dbt?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-automatizar-ej4","opciones":[{"text":"Una scheduled query","ok":false},{"text":"Una vista","ok":false},{"text":"Un orquestador como Airflow o Cloud Composer","ok":true},{"text":"Una vista materializada","ok":false}],"enunciado":"<p>El flujo descarga de una API, carga en BigQuery y avisa por Slack. ¿Qué conviene?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true}]},"bigquery-paso-a-paso-acceso-y-gobierno":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Llaves por departamento y una ventanilla</div>\n\n<p>Los permisos de BigQuery son llaves: conviene dar la llave de un departamento (un dataset), no la del edificio (el proyecto). Una vista autorizada es una ventanilla: entrega solo lo que comercial necesita, aunque comercial no tenga llave del depósito de atrás.</p>\n</div>\n\n\n<h2>Paso 1 — Una vista para comercial</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">CREATE SCHEMA IF NOT EXISTS reportes;\n\n-- solo lo que comercial necesita: sin email ni teléfono\nCREATE OR REPLACE VIEW reportes.v_clientes_por_pais AS\nSELECT pais, segmento, COUNT(*) AS clientes\nFROM tienda.clientes\nGROUP BY pais, segmento;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q19-vista.webp\" alt=\"El dataset reportes con la vista (1), la vista sin datos personales (2) y su resultado por país y segmento (3)\" loading=\"lazy\"><figcaption>El dataset reportes con la vista (1), la vista sin datos personales (2) y su resultado por país y segmento (3)</figcaption></figure>\n\n\n<p>Para que comercial lea la vista <strong>sin</strong> tener acceso a <code>tienda.clientes</code>, en BigQuery real se marca como <strong>vista autorizada</strong>: se autoriza la vista (o todo el dataset <code>reportes</code>) en el dataset <code>tienda</code>, y se le da a comercial acceso solo a <code>reportes</code>.</p>\n<h2>Paso 2 — Los roles</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Rol de IAM</th>\n<th>Permite</th>\n<th>Para</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>BigQuery Data Viewer</strong></td>\n<td>Leer tablas y vistas</td>\n<td>Analistas (a nivel de dataset)</td>\n</tr>\n<tr>\n<td><strong>BigQuery Data Editor</strong></td>\n<td>Leer y escribir tablas</td>\n<td>Procesos de carga, ingeniería</td>\n</tr>\n<tr>\n<td><strong>BigQuery Data Owner</strong></td>\n<td>Todo sobre el dataset, incluidos sus permisos</td>\n<td>Responsables del dataset</td>\n</tr>\n<tr>\n<td><strong>BigQuery Job User</strong></td>\n<td>Ejecutar jobs (consultas) en el proyecto</td>\n<td>Cualquiera que consulte: <strong>sin este rol no se puede correr nada</strong></td>\n</tr>\n<tr>\n<td><strong>BigQuery Admin</strong></td>\n<td>Todo</td>\n<td>Muy pocas personas</td>\n</tr>\n</tbody></table></div>\n<p>Los permisos se dan a <strong>grupos</strong> (<code>grp-comercial@tienda.example</code>) y al nivel más chico posible: el dataset, no todo el proyecto.</p>\n<h2>Paso 3 — Seguridad fina</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">-- cada gerente ve solo las filas de su país\nCREATE ROW ACCESS POLICY solo_peru\nON analitica.hechos_ventas\nGRANT TO (&quot;group:gerencia-pe@tienda.example&quot;)\nFILTER USING (pais = 'Perú');</code></pre>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Herramienta</th>\n<th>Protege</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Row access policies</strong></td>\n<td>Filas según quién consulta</td>\n</tr>\n<tr>\n<td><strong>Policy tags</strong> (Dataplex)</td>\n<td>Columnas sensibles: sin permiso, la columna no se puede leer</td>\n</tr>\n<tr>\n<td><strong>Enmascaramiento dinámico</strong></td>\n<td>Muestra la columna enmascarada (<code>****</code>, hash) a quien no debe verla completa</td>\n</tr>\n<tr>\n<td><strong>Vistas autorizadas</strong></td>\n<td>Exponen solo un subconjunto sin dar acceso a la tabla de fondo</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 4 — Compartir sin copiar</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q19-sharing.webp\" alt=\"Sharing (Analytics Hub) - publicar datasets para otras organizaciones sin copiarlos\" loading=\"lazy\"><figcaption>Sharing (Analytics Hub) - publicar datasets para otras organizaciones sin copiarlos</figcaption></figure>\n\n\n<p>Con <strong>Analytics Hub</strong> se publica un dataset y el otro lo ve como un dataset enlazado de solo lectura; cada uno paga sus propias consultas.</p>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Dar los roles a nivel proyecto.</strong> Data Viewer en el proyecto abre todos los datasets; dalo en el dataset que corresponde.</li>\n<li><strong>Olvidar Job User.</strong> Leer la tabla no alcanza para consultar: hace falta poder crear jobs en algún proyecto.</li>\n<li><strong>Compartir copias.</strong> Cada copia se desactualiza y es un riesgo más; comparte con vistas autorizadas o Analytics Hub.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Creaste una vista para un área.</li>\n<li>Conoces los roles de IAM de BigQuery.</li>\n<li>Sabes restringir filas y columnas y compartir sin copiar.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-acceso-y-gobierno-ej1","opciones":[{"text":"Data Owner","ok":false},{"text":"BigQuery Job User","ok":true},{"text":"Storage Admin","ok":false},{"text":"BigQuery Data Editor en el dataset","ok":false}],"enunciado":"<p>¿Qué rol hace falta, además de leer la tabla, para ejecutar consultas en un proyecto?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-acceso-y-gobierno-ej2","opciones":[{"text":"Una vista que puede leer tablas a las que el usuario final no tiene acceso","ok":true},{"text":"Una vista sin datos","ok":false},{"text":"Una vista que solo puede leer el dueño del proyecto","ok":false},{"text":"Una tabla temporal","ok":false}],"enunciado":"<p>¿Qué es una vista autorizada?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-acceso-y-gobierno-ej3","opciones":[{"text":"Una tabla por gerente","ok":false},{"text":"Con una row access policy","ok":true},{"text":"Con una etiqueta de política en la columna país","ok":false},{"text":"Con una scheduled query","ok":false}],"enunciado":"<p>¿Cómo haces que cada gerente vea solo su país en la misma tabla?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-acceso-y-gobierno-ej4","opciones":[{"text":"Exportándolo a CSV","ok":false},{"text":"Publicándolo en Analytics Hub","ok":true},{"text":"Dándole el rol Owner de tu proyecto","ok":false},{"text":"Con una scheduled query que copia los datos a su proyecto","ok":false}],"enunciado":"<p>¿Cómo compartes un dataset con otra empresa sin copiarlo?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true}]},"bigquery-paso-a-paso-proyecto-costo-bajo-control":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El objetivo</div>\n\n<p>Finanzas: <em>&quot;La factura de BigQuery subió. Queremos saber qué la explica, qué van a cambiar y cómo evitamos sorpresas.&quot;</em></p>\n</div>\n\n\n<h2>Criterio de aceptación</h2>\n<ul>\n<li>Un número: bytes procesados, facturados y costo on-demand del periodo.</li>\n<li>Las tres consultas más caras con una mejora concreta para cada una.</li>\n<li>Una regla de límites (bytes máximos por consulta o por día) y de accesos.</li>\n<li>Todo en un informe de media página.</li>\n</ul>\n<h2>Cómo se ve terminado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q20-costos.webp\" alt=\"El resumen de costos (1) y las consultas más caras con su costo a escala real (2)\" loading=\"lazy\"><figcaption>El resumen de costos (1) y las consultas más caras con su costo a escala real (2)</figcaption></figure>\n\n\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q20-jobs.webp\" alt=\"El historial de jobs para ver quién corrió cada consulta y si salió de la caché\" loading=\"lazy\"><figcaption>El historial de jobs para ver quién corrió cada consulta y si salió de la caché</figcaption></figure>\n\n\n<details><summary>💡 Solución comentada</summary>\n\n<p><strong>Medir</strong> (también con SQL, lección 17):</p>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">SELECT user_email, COUNT(*) AS consultas,\n       ROUND(SUM(total_bytes_billed) / POW(1024, 4) * 6.25, 4) AS usd\nFROM `region-us`.INFORMATION_SCHEMA.JOBS\nWHERE job_type = 'QUERY'\n  AND creation_time &gt;= TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 30 DAY)\nGROUP BY user_email\nORDER BY usd DESC;</code></pre>\n<p><strong>Mejoras típicas para las más caras:</strong></p>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Problema</th>\n<th>Mejora</th>\n</tr>\n</thead><tbody><tr>\n<td><code>SELECT *</code> sobre la tabla de pedidos</td>\n<td>Nombrar las columnas</td>\n</tr>\n<tr>\n<td>Filtro con <code>EXTRACT(YEAR FROM fecha)</code></td>\n<td>Filtro directo sobre la columna de partición</td>\n</tr>\n<tr>\n<td>Una vista con JOIN que se consulta cien veces por día</td>\n<td>Materializarla en una tabla particionada (o una vista materializada)</td>\n</tr>\n<tr>\n<td>La misma consulta del tablero cada 5 minutos</td>\n<td>Que el tablero use la caché o una tabla resumen</td>\n</tr>\n</tbody></table></div>\n<p><strong>Límites y accesos:</strong></p>\n<ul>\n<li><strong>Maximum bytes billed</strong> en las consultas de herramientas y cuotas diarias por usuario o proyecto.</li>\n<li><code>require_partition_filter</code> en las tablas grandes.</li>\n<li>Data Viewer por dataset (no por proyecto) y Job User solo a quien consulta.</li>\n<li>Si el volumen es grande y estable, evaluar el modelo de capacidad (ediciones) para tener un costo predecible.</details></li>\n</ul>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Optimizar sin medir.</strong> Primero identifica con datos las consultas que más facturan; optimizar las que no pesan no mueve la factura.</li>\n<li><strong>Proponer <code>LIMIT</code> como ahorro.</strong> No baja lo leído; las mejoras reales son columnas justas, filtro de partición y tablas resumen.</li>\n<li><strong>Dar acceso amplio para &quot;no molestar&quot;.</strong> Data Viewer por proyecto y Job User para todos multiplican quién puede generar costo.</li>\n</ul>\n</div>\n\n\n<h2>Lo que aprendiste en el nivel 5</h2>\n<ul>\n<li>INFORMATION_SCHEMA.</li>\n<li>Scheduled queries, Dataform y orquestadores.</li>\n<li>IAM, vistas autorizadas y seguridad fina.</li>\n</ul>\n<p>En el nivel 6: buenas prácticas, capacidad, BigQuery real y el proyecto final.</p>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-costo-bajo-control-ej1","opciones":[{"text":"Maximum bytes billed (y cuotas diarias)","ok":true},{"text":"Más LIMIT","ok":false},{"text":"Cambiar de región","ok":false},{"text":"Borrar el historial","ok":false}],"enunciado":"<p>¿Qué ajuste evita que una consulta por error procese terabytes?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-costo-bajo-control-ej2","opciones":[{"text":"Nada","ok":false},{"text":"Materializar el resultado en una tabla (o una vista materializada)","ok":true},{"text":"Agregar LIMIT","ok":false},{"text":"Moverla a otro dataset","ok":false}],"enunciado":"<p>Una vista con JOIN se consulta cien veces por día. ¿Qué mejora propones?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-costo-bajo-control-ej3","opciones":[{"text":"Con pocas consultas chicas","ok":false},{"text":"Con mucho volumen estable, para tener un costo predecible","ok":true},{"text":"Cuando hay picos aislados una vez por mes","ok":false},{"text":"Solo para cargas","ok":false}],"enunciado":"<p>¿Cuándo conviene evaluar el modelo de capacidad (ediciones)?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-costo-bajo-control-ej4","opciones":[{"text":"dataset.INFORMATION_SCHEMA.TABLES","ok":false},{"text":"region-us.INFORMATION_SCHEMA.JOBS agrupando por user_email","ok":true},{"text":"Preview","ok":false},{"text":"COLUMNS","ok":false}],"enunciado":"<p>¿Con qué vista sabes cuánto gastó cada usuario?</p>\n","dificultad":"5 · Avanzado","dificultadLeccion":true}]},"bigquery-paso-a-paso-buenas-practicas":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Qué cajones, qué estantes, qué carpetas</div>\n\n<p>Leer menos es abrir solo los cajones que necesitas (las columnas), en los estantes de las fechas pedidas (la partición) y, dentro de cada estante, solo las carpetas del canal buscado (el clustering). Cada palanca sola ayuda; las tres juntas son las que hacen que una consulta lea el 2 % de la tabla.</p>\n</div>\n\n\n<h2>Paso 1 — Las tres palancas juntas</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">-- columnas justas + filtro de partición + clustering\nSELECT canal, COUNT(*) AS pedidos\nFROM analitica.pedidos_part\nWHERE fecha_pedido BETWEEN '2024-12-01' AND '2024-12-31'\n  AND canal = 'web'\nGROUP BY canal;</code></pre>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q21-optimizada.webp\" alt=\"La estimación (1) y lo que realmente se leyó - 2 columnas y el 2 % de la tabla gracias a la partición y el clustering (2)\" loading=\"lazy\"><figcaption>La estimación (1) y lo que realmente se leyó - 2 columnas y el 2 % de la tabla gracias a la partición y el clustering (2)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Palanca</th>\n<th>Efecto</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Columnas</strong></td>\n<td>Solo se leen las nombradas</td>\n</tr>\n<tr>\n<td><strong>Partición</strong></td>\n<td>Solo se leen las particiones del filtro</td>\n</tr>\n<tr>\n<td><strong>Clustering</strong></td>\n<td>Dentro de cada partición, se saltan los bloques que no tienen ese canal</td>\n</tr>\n</tbody></table></div>\n<h2>Paso 2 — Hábitos</h2>\n<p><strong>Consultas</strong></p>\n<ul>\n<li>Nombrar columnas; <code>SELECT * EXCEPT(...)</code> si hacen falta casi todas.</li>\n<li>Filtrar por la partición <strong>antes</strong> de unir tablas grandes.</li>\n<li>Mirar el validador antes de ejecutar y el &quot;qué se leyó&quot; después.</li>\n<li>Para explorar: Preview, no <code>LIMIT</code>.</li>\n</ul>\n<p><strong>Tablas</strong></p>\n<ul>\n<li>Particionar las tablas grandes por la fecha de uso y exigir el filtro.</li>\n<li>Clustering por las columnas que más se filtran (hasta 4).</li>\n<li>Desnormalizar o anidar (<code>ARRAY&lt;STRUCT&gt;</code>) cuando un JOIN se repite mucho.</li>\n<li><strong>Vistas materializadas</strong> para agregados que se consultan seguido: BigQuery las mantiene al día y las usa solo.</li>\n</ul>\n<p><strong>Cargas</strong></p>\n<ul>\n<li>Cargas por lotes (gratis) antes que streaming si no hace falta al instante.</li>\n<li>MERGE idempotente para incrementales.</li>\n<li>Vencimiento automático para tablas temporales.</li>\n</ul>\n<p><strong>Equipo</strong></p>\n<ul>\n<li>Datasets por capa y por equipo, con permisos por dataset.</li>\n<li>Límite de bytes por consulta y cuotas diarias.</li>\n<li>SQL versionado (Dataform o dbt), no consultas sueltas en pestañas.</li>\n</ul>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Unir antes de filtrar.</strong> Un JOIN con la tabla grande completa procesa todo; filtra por fecha antes del JOIN.</li>\n<li><strong>Tablas temporales sin vencimiento.</strong> Se acumulan y cobran almacenamiento; ponles vencimiento al crearlas.</li>\n<li><strong>Streaming por costumbre.</strong> Si los datos pueden esperar unos minutos, la carga por lotes es gratis.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Combinaste las tres palancas.</li>\n<li>Tienes una lista de hábitos para consultas, tablas, cargas y equipo.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-buenas-practicas-ej1","opciones":[{"text":"Columnas justas, filtro de partición y clustering","ok":true},{"text":"LIMIT, ORDER BY y DISTINCT","ok":false},{"text":"Más slots, más regiones y más usuarios","ok":false},{"text":"Vistas, comentarios y alias","ok":false}],"enunciado":"<p>¿Cuáles son las tres palancas para leer menos datos?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-buenas-practicas-ej2","opciones":[{"text":"Para que el JOIN trabaje con menos filas y se lean menos particiones","ok":true},{"text":"Porque BigQuery no permite JOIN sin filtro de partición","ok":false},{"text":"Porque así la consulta sale de la caché","ok":false},{"text":"No cambia nada","ok":false}],"enunciado":"<p>¿Por qué conviene filtrar por la partición antes de unir con una tabla enorme?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-buenas-practicas-ej3","opciones":[{"text":"Para datos que nunca se consultan","ok":false},{"text":"Para agregados que se consultan seguido: BigQuery los mantiene al día","ok":true},{"text":"Para borrar datos","ok":false},{"text":"Para tablas que cambian cada segundo y se consultan una vez al mes","ok":false}],"enunciado":"<p>¿Cuándo conviene una vista materializada?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-buenas-practicas-ej4","opciones":[{"text":"Dejarlas para siempre","ok":false},{"text":"Un vencimiento automático","ok":true},{"text":"Copiarlas","ok":false},{"text":"Hacerlas vistas","ok":false}],"enunciado":"<p>¿Qué conviene para tablas temporales que nadie limpia?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true}]},"bigquery-paso-a-paso-capacidad-y-mas":{"html":"<div class=\"callout callout-nota\"><div class=\"callout-title\">📝 En la práctica</div>\n\n<p>Estas secciones no están simuladas: la práctica te muestra qué son. El SQL es el de BigQuery real (BigQuery ML también se puede probar con <code>bq query</code> en la <a href=\"#/lab/terminal\">terminal del curso</a>).</p>\n</div>\n\n\n<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Pagar por kilo o contratar una cuadrilla</div>\n\n<p>Un slot es un trabajador que procesa parte de la consulta. En on-demand pagas por kilo procesado (los bytes), sin importar cuántos trabajadores se usaron. En el modelo de capacidad contratas una cuadrilla por hora: conviene cuando tienes trabajo grande y constante.</p>\n</div>\n\n\n<h2>Paso 1 — Slots y ediciones</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q22-capacidad.webp\" alt=\"Capacity management - reservas de slots con las ediciones Standard, Enterprise y Enterprise Plus\" loading=\"lazy\"><figcaption>Capacity management - reservas de slots con las ediciones Standard, Enterprise y Enterprise Plus</figcaption></figure>\n\n\n<p>Un <strong>slot</strong> es una unidad de cómputo virtual: una consulta usa muchos slots en paralelo durante unos segundos.</p>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Modelo</th>\n<th>Se paga</th>\n<th>Conviene</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>On-demand</strong></td>\n<td>Bytes procesados</td>\n<td>Uso variable o chico; empezar</td>\n</tr>\n<tr>\n<td><strong>Capacidad (ediciones)</strong></td>\n<td>Slots por hora, con autoescalado y compromisos de 1 o 3 años</td>\n<td>Volumen grande y estable; costo predecible</td>\n</tr>\n</tbody></table></div>\n<p>Las ediciones (Standard, Enterprise, Enterprise Plus) se diferencian en funciones de seguridad, gobierno y disponibilidad.</p>\n<h2>Paso 2 — Data Transfer Service</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q22-transferencias.webp\" alt=\"Data transfers - copias programadas desde Google Ads, YouTube, Cloud Storage, Amazon S3 y otras fuentes\" loading=\"lazy\"><figcaption>Data transfers - copias programadas desde Google Ads, YouTube, Cloud Storage, Amazon S3 y otras fuentes</figcaption></figure>\n\n\n<h2>Paso 3 — BigQuery ML</h2>\n<pre data-lang=\"sql\" data-norun tabindex=\"0\"><code class=\"language-sql\">-- ¿qué clientes van a volver a comprar? un modelo con SQL\nCREATE OR REPLACE MODEL analitica.modelo_recompra\nOPTIONS (model_type = 'logistic_reg', input_label_cols = ['volvio']) AS\nSELECT pais, segmento, pedidos_previos, dias_desde_ultimo, volvio\nFROM analitica.entrenamiento_clientes;\n\nSELECT * FROM ML.EVALUATE(MODEL analitica.modelo_recompra);\nSELECT cliente_id, predicted_volvio_probs\nFROM ML.PREDICT(MODEL analitica.modelo_recompra, TABLE analitica.clientes_actuales);</code></pre>\n<p>Entrenar y predecir sin sacar los datos de BigQuery: regresión, clasificación, series de tiempo (<code>ARIMA_PLUS</code>), k-means y modelos remotos de Vertex AI.</p>\n<h2>Paso 4 — Más piezas</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Pieza</th>\n<th>Para</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>BI Engine</strong></td>\n<td>Una caché en memoria que acelera tableros (Looker Studio, Looker, Power BI)</td>\n</tr>\n<tr>\n<td><strong>Vistas materializadas</strong></td>\n<td>Agregados precalculados y mantenidos al día</td>\n</tr>\n<tr>\n<td><strong>Search indexes</strong></td>\n<td>Búsquedas de texto en tablas enormes (<code>SEARCH(...)</code>)</td>\n</tr>\n<tr>\n<td><strong>Funciones de IA</strong></td>\n<td>Resumir, clasificar o generar texto desde SQL con modelos de Vertex AI</td>\n</tr>\n<tr>\n<td><strong>BigLake</strong></td>\n<td>Consultar archivos abiertos (Parquet, Iceberg) en Cloud Storage con la misma seguridad</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Pasar a capacidad sin medir.</strong> Con pocas consultas, el modelo on-demand suele ser más barato; mira antes <code>INFORMATION_SCHEMA.JOBS</code>.</li>\n<li><strong>Usar un modelo de BigQuery ML sin evaluarlo.</strong> <code>ML.EVALUATE</code> sobre datos que el modelo no vio dice si sirve.</li>\n<li><strong>Esperar que BI Engine arregle un mal diseño.</strong> Acelera tableros, pero una tabla sin partición sigue leyendo de más.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Entiendes slots y ediciones.</li>\n<li>Conoces Data Transfer Service y BigQuery ML.</li>\n<li>Ubicas las demás piezas de la plataforma.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-capacidad-y-mas-ej1","opciones":[{"text":"Una unidad de cómputo virtual que ejecuta parte de una consulta","ok":true},{"text":"Un dataset","ok":false},{"text":"Una partición","ok":false},{"text":"Una conexión abierta a la consola","ok":false}],"enunciado":"<p>¿Qué es un slot en BigQuery?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-capacidad-y-mas-ej2","opciones":[{"text":"Con dos consultas por semana","ok":false},{"text":"Con volumen grande y estable, buscando un costo predecible","ok":true},{"text":"Con picos esporádicos y poco volumen","ok":false},{"text":"Solo para cargas","ok":false}],"enunciado":"<p>¿Cuándo conviene el modelo de capacidad (ediciones)?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-capacidad-y-mas-ej3","opciones":[{"text":"TRAIN TABLE","ok":false},{"text":"CREATE MODEL ... OPTIONS (model_type = ...) AS SELECT ...","ok":true},{"text":"ML.FIT()","ok":false},{"text":"No se puede con SQL","ok":false}],"enunciado":"<p>¿Qué sentencia entrena un modelo en BigQuery ML?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-capacidad-y-mas-ej4","opciones":[{"text":"Para cargar archivos","ok":false},{"text":"Para acelerar tableros con una caché en memoria","ok":true},{"text":"Para dar permisos","ok":false},{"text":"Para guardar copias de las tablas por 7 días","ok":false}],"enunciado":"<p>¿Para qué sirve BI Engine?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true}]},"bigquery-paso-a-paso-de-la-practica-a-bigquery-real":{"html":"<div class=\"callout callout-analogia\"><div class=\"callout-title\">🧠 Del simulador al avión</div>\n\n<p>Pasar de la práctica a BigQuery real es pasar del simulador de vuelo al avión: los controles son los mismos (GoogleSQL, particiones, MERGE, time travel), pero el combustible se paga de verdad y hay más gente a bordo con distintos permisos.</p>\n</div>\n\n\n<h2>Paso 1 — Qué cambia</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>En la práctica</th>\n<th>En BigQuery real</th>\n</tr>\n</thead><tbody><tr>\n<td>Tablas de miles de filas en tu navegador</td>\n<td>Tablas de miles de millones de filas en Google Cloud</td>\n</tr>\n<tr>\n<td>Costos de centavos</td>\n<td>Una consulta mal escrita puede leer terabytes</td>\n</tr>\n<tr>\n<td>Sin IAM</td>\n<td>Roles de IAM, grupos y cuentas de servicio</td>\n</tr>\n<tr>\n<td>Scheduled queries, Dataform y transferencias explicados</td>\n<td>Disponibles</td>\n</tr>\n</tbody></table></div>\n<p>Lo que <strong>no</strong> cambia: GoogleSQL, el validador, particiones, clustering, MERGE, time travel e INFORMATION_SCHEMA.</p>\n<h2>Paso 2 — Empezar gratis</h2>\n<p>El <strong>sandbox de BigQuery</strong> funciona sin tarjeta: 10 GB de almacenamiento y 1 TB de consultas por mes, con tablas que vencen a los 60 días. Para seguir después, se activa la facturación del proyecto y conviene poner antes un <strong>presupuesto con alertas</strong> y cuotas de consulta.</p>\n<p>Hay datasets públicos para practicar con volumen real (<code>bigquery-public-data</code>).</p>\n<h2>Paso 3 — La CLI bq</h2>\n<p>En la <a href=\"#/lab/terminal\">terminal del curso</a>:</p>\n<pre data-lang=\"bash\" data-norun tabindex=\"0\"><code class=\"language-bash\">gcloud auth login\ngcloud config set project tienda-andina-dev\nbq ls\nbq query --use_legacy_sql=false 'SELECT canal, COUNT(*) AS pedidos FROM tienda.pedidos GROUP BY canal'</code></pre>\n<details class=\"bx\"><summary>🔍 Qué hace cada comando <span>(4)</span></summary><ol><li><code class=\"bx-linea\">gcloud auth login</code><span><code>gcloud</code>: la CLI de Google Cloud: hace desde la terminal lo mismo que la consola de Google Cloud. <code>auth</code> inicia sesión y maneja credenciales (<code>login</code>)</span></li><li><code class=\"bx-linea\">gcloud config set project tienda-andina-dev</code><span><code>gcloud</code>: la CLI de Google Cloud: hace desde la terminal lo mismo que la consola de Google Cloud. <code>config</code> elige proyecto, región y otros valores por defecto (<code>set project</code>)</span></li><li><code class=\"bx-linea\">bq ls</code><span><code>bq</code>: la CLI de BigQuery. <code>ls</code> lista datasets o tablas</span></li><li><code class=\"bx-linea\">bq query --use_legacy_sql=false 'SELECT canal, COUNT(*) AS pedidos FROM tienda.pedidos GROUP BY canal'</code><span><code>bq</code>: la CLI de BigQuery. <code>query</code> ejecuta una consulta SQL</span></li></ol><p class=\"bx-donde\">Se escribe en la <b>terminal</b>: la del curso (botón ⌨ Terminal) o la de tu computadora — <b>Terminal</b> en macOS, <b>Ubuntu (WSL)</b> o <b>Git Bash</b> en Windows. Escribe una línea y presiona Enter.</p></details>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q23-bq-cli.webp\" alt=\"bq ls y bq query en la terminal del curso (con su propio proyecto simulado)\" loading=\"lazy\"><figcaption>bq ls y bq query en la terminal del curso (con su propio proyecto simulado)</figcaption></figure>\n\n\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Comando</th>\n<th>Para</th>\n</tr>\n</thead><tbody><tr>\n<td><code>bq query --dry_run --use_legacy_sql=false &#39;...&#39;</code></td>\n<td>Ver los bytes sin ejecutar</td>\n</tr>\n<tr>\n<td><code>bq query --maximum_bytes_billed=1000000000 ...</code></td>\n<td>Cortar si supera 1 GB</td>\n</tr>\n<tr>\n<td><code>bq mk --dataset --location=US proyecto:analitica</code></td>\n<td>Crear un dataset</td>\n</tr>\n<tr>\n<td><code>bq load ...</code> / <code>bq extract ...</code></td>\n<td>Cargar y exportar</td>\n</tr>\n<tr>\n<td><code>bq show --format=prettyjson tienda.pedidos</code></td>\n<td>Ver el esquema y los detalles</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-nota\"><div class=\"callout-title\">📝 Legacy SQL</div>\n\n<p><code>--use_legacy_sql=false</code> usa GoogleSQL. Legacy SQL es el dialecto antiguo; no lo uses en código nuevo.</p>\n</div>\n\n\n<h2>Paso 4 — Conectar herramientas</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Herramienta</th>\n<th>Cómo</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Python</strong></td>\n<td><code>google-cloud-bigquery</code> (y <code>bigframes</code> para trabajar con DataFrames que corren en BigQuery)</td>\n</tr>\n<tr>\n<td><strong>Looker Studio / Power BI / Tableau</strong></td>\n<td>Conector nativo con un rol de lectura</td>\n</tr>\n<tr>\n<td><strong>dbt / Dataform</strong></td>\n<td>Con una cuenta de servicio de transformación</td>\n</tr>\n<tr>\n<td><strong>Airflow / Cloud Composer</strong></td>\n<td>Provider de Google y una conexión con cuenta de servicio</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-cuidado\"><div class=\"callout-title\">⚠️ Cuentas de servicio</div>\n\n<p>Los procesos automáticos usan <strong>cuentas de servicio</strong> con el rol mínimo, idealmente sin claves descargadas (Workload Identity). Nunca subas un archivo de credenciales a Git.</p>\n</div>\n\n\n<h2>Paso 5 — Tu primera semana</h2>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Presupuesto con alertas y cuota diaria de bytes en el proyecto.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Tu acceso: Job User en el proyecto y Data Viewer en los datasets que necesitas.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Revisar <code>INFORMATION_SCHEMA.JOBS</code> para entender qué corre y cuánto cuesta.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Aprender las tablas grandes: cómo están particionadas y con qué clustering.</li>\n<li><input disabled=\"\" type=\"checkbox\" aria-label=\"Pendiente\">  Cada consulta, primero con el validador.</li>\n</ul>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Conectar procesos automáticos con tu usuario personal.</strong> Si te vas o cambias de contraseña, se rompen; usa cuentas de servicio con el rol mínimo.</li>\n<li><strong>Subir un archivo de credenciales a Git.</strong> Aunque lo borres después, queda en el historial; revoca la clave y usa Workload Identity.</li>\n<li><strong>Activar la facturación sin presupuesto.</strong> Configura alertas y cuotas de bytes el primer día.</li>\n</ul>\n</div>\n\n\n<h2>✅ Lo que lograste</h2>\n<ul>\n<li>Sabes qué cambia en BigQuery real.</li>\n<li>Sabes empezar gratis y usar la CLI.</li>\n<li>Sabes conectar herramientas de forma segura.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-de-la-practica-a-bigquery-real-ej1","opciones":[{"text":"10 GB de almacenamiento y 1 TB de consultas por mes, con tablas que vencen a los 60 días","ok":true},{"text":"Todo ilimitado","ok":false},{"text":"1 TB de almacenamiento y consultas ilimitadas","ok":false},{"text":"Solo consultas sobre datasets públicos, sin tablas propias","ok":false}],"enunciado":"<p>¿Qué ofrece el sandbox de BigQuery sin tarjeta?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-de-la-practica-a-bigquery-real-ej2","opciones":[{"text":"bq ls","ok":false},{"text":"bq query --dry_run","ok":true},{"text":"bq show","ok":false},{"text":"bq mk","ok":false}],"enunciado":"<p>¿Cómo ves con bq cuántos bytes procesaría una consulta sin ejecutarla?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-de-la-practica-a-bigquery-real-ej3","opciones":[{"text":"Tu usuario personal","ok":false},{"text":"Una cuenta de servicio con el rol mínimo","ok":true},{"text":"Un usuario Admin compartido","ok":false},{"text":"Sin identidad","ok":false}],"enunciado":"<p>¿Con qué identidad debería conectarse un proceso automático como dbt o Airflow?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-de-la-practica-a-bigquery-real-ej4","opciones":[{"text":"Una reserva de capacidad por 3 años","ok":false},{"text":"Un presupuesto con alertas y cuotas de bytes","ok":true},{"text":"Un dataset por usuario, sin vencimiento","ok":false},{"text":"Permisos de Admin para todos","ok":false}],"enunciado":"<p>¿Qué configuras el primer día en un proyecto con facturación?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true}]},"bigquery-paso-a-paso-proyecto-final-analitica-tienda-andina":{"html":"<div class=\"callout callout-escenario\"><div class=\"callout-title\">🏢 El encargo</div>\n\n<p>Gerencia de Tienda Andina: <em>&quot;Queremos ventas, eventos de la app y stock en BigQuery, con vistas para comercial y operaciones, que cueste poco aunque los datos crezcan cien veces, y que podamos recuperarnos si alguien se equivoca.&quot;</em></p>\n</div>\n\n\n<h2>Requisitos</h2>\n<p><strong>Estructura</strong></p>\n<ol>\n<li>Datasets <code>analitica</code> y <code>reportes</code>, creados con un script que se pueda repetir.</li>\n<li><code>analitica.hechos_ventas</code> particionada por fecha y con clustering según las consultas de comercial.</li>\n<li><code>analitica.eventos_app</code> cargada desde archivo y particionada por fecha.</li>\n</ol>\n<p><strong>Lógica</strong>\n4. Una vista para comercial en <code>reportes</code> sin datos personales.\n5. <code>analitica.stock_tiendas</code> actualizada con un MERGE idempotente.\n6. Una consulta de tendencia mensual con QUALIFY o funciones de ventana.</p>\n<p><strong>Operación</strong>\n7. Procedimiento de recuperación con time travel (y snapshot antes de cargas grandes).\n8. Inventario y control de costos con <code>INFORMATION_SCHEMA</code>.\n9. Tabla de accesos (roles de IAM por dataset) y límites de bytes.</p>\n<h2>Cómo se ve terminado</h2>\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q24-explorer.webp\" alt=\"El proyecto con analitica (tablas particionadas, vistas, stock) y reportes (la vista para comercial)\" loading=\"lazy\"><figcaption>El proyecto con analitica (tablas particionadas, vistas, stock) y reportes (la vista para comercial)</figcaption></figure>\n\n\n<figure class=\"captura\"><img src=\"assets/img/guias/bigquery/q24-dataset.webp\" alt=\"El dataset analitica - tablas particionadas, tablas comunes y la vista, con filas y tamaño\" loading=\"lazy\"><figcaption>El dataset analitica - tablas particionadas, tablas comunes y la vista, con filas y tamaño</figcaption></figure>\n\n\n<h2>Entregable: el documento de una página</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Sección</th>\n<th>Qué responde</th>\n</tr>\n</thead><tbody><tr>\n<td><strong>Diseño</strong></td>\n<td>Datasets, tablas, partición y clustering de cada una, y por qué</td>\n</tr>\n<tr>\n<td><strong>Cargas</strong></td>\n<td>Cómo llegan los datos y cómo se evita duplicar</td>\n</tr>\n<tr>\n<td><strong>Accesos</strong></td>\n<td>Qué rol tiene cada grupo y qué vistas usa cada área</td>\n</tr>\n<tr>\n<td><strong>Recuperación</strong></td>\n<td>Qué hacer ante un borrado o una carga mala</td>\n</tr>\n<tr>\n<td><strong>Costos</strong></td>\n<td>Bytes de las consultas típicas, costo mensual estimado y límites</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-errores\"><div class=\"callout-title\">🐞 Errores frecuentes</div>\n\n<ul>\n<li><strong>Diseñar las tablas antes de conocer las consultas.</strong> La partición y el clustering salen de cómo filtra cada área; pregúntalo primero.</li>\n<li><strong>Dar por buena la carga sin correrla dos veces.</strong> La idempotencia se prueba, no se supone.</li>\n<li><strong>Escribir el procedimiento de recuperación sin probarlo.</strong> Provoca un borrado en una copia y restáurala siguiendo tu documento.</li>\n</ul>\n</div>\n\n\n<h2>✅ Rúbrica</h2>\n<div class=\"table-wrap\"><table><thead><tr>\n<th>Criterio</th>\n<th>Cumple</th>\n<th>Destaca</th>\n</tr>\n</thead><tbody><tr>\n<td>Diseño</td>\n<td>Tablas grandes particionadas</td>\n<td>Clustering justificado con las consultas reales y <code>require_partition_filter</code></td>\n</tr>\n<tr>\n<td>Cargas</td>\n<td>MERGE funciona</td>\n<td>Idempotencia comprobada corriendo dos veces</td>\n</tr>\n<tr>\n<td>Consultas</td>\n<td>Resultados correctos</td>\n<td>Cada consulta típica lee una fracción mínima (mostrar &quot;qué se leyó&quot;)</td>\n</tr>\n<tr>\n<td>Accesos</td>\n<td>Vista sin datos personales</td>\n<td>Vista autorizada y row access policy propuestas</td>\n</tr>\n<tr>\n<td>Recuperación</td>\n<td>Procedimiento escrito</td>\n<td>Probado con un borrado provocado</td>\n</tr>\n<tr>\n<td>Costos</td>\n<td>Estimación mensual</td>\n<td>Tablero con <code>INFORMATION_SCHEMA.JOBS</code> y límites de bytes</td>\n</tr>\n</tbody></table></div>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">💡 Para tu portafolio</div>\n\n<p>Sube el SQL, el documento y capturas <strong>de la práctica</strong> (o del sandbox con datos públicos) a un repositorio con un README claro. Si te preparas para la certificación <strong>Professional Data Engineer</strong> de Google Cloud, revisa el banco de preguntas en <a href=\"#/m/cert-gcp\">Certificaciones GCP</a>: diseño de tablas, costos y seguridad en BigQuery son de lo más evaluado.</p>\n</div>\n\n\n<h2>Lo que aprendiste en el curso</h2>\n<ul>\n<li><strong>Nivel 1:</strong> qué es BigQuery, consultas, bytes y exploración.</li>\n<li><strong>Nivel 2:</strong> datasets, costos, caché y jobs.</li>\n<li><strong>Nivel 3:</strong> particiones, clustering, cargas y datos anidados.</li>\n<li><strong>Nivel 4:</strong> MERGE, time travel y SQL analítico.</li>\n<li><strong>Nivel 5:</strong> INFORMATION_SCHEMA, automatización, accesos y costos.</li>\n<li><strong>Nivel 6:</strong> buenas prácticas, capacidad, BigQuery real.</li>\n</ul>\n<div class=\"exercise-slot\" data-ex=\"0\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"1\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"2\"></div>\n\n\n\n<div class=\"exercise-slot\" data-ex=\"3\"></div>\n\n","ejercicios":[{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-final-analitica-tienda-andina-ej1","opciones":[{"text":"Partición por fecha, clustering por sus filtros y columnas justas","ok":true},{"text":"LIMIT 100","ok":false},{"text":"Usar vistas sin filtros","ok":false},{"text":"Copiar la tabla cada día","ok":false}],"enunciado":"<p>¿Qué hace que la consulta típica de comercial cueste poco aunque los datos crezcan cien veces?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-final-analitica-tienda-andina-ej2","opciones":[{"text":"Pidiéndole por escrito que no consulte esas columnas","ok":false},{"text":"Con una vista (autorizada) sin esas columnas y acceso solo a reportes","ok":true},{"text":"Borrando las columnas de la tabla original","ok":false},{"text":"Con una scheduled query que borra esas columnas cada noche","ok":false}],"enunciado":"<p>¿Cómo te aseguras de que comercial no vea datos personales?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-final-analitica-tienda-andina-ej3","opciones":[{"text":"Un snapshot de la tabla","ok":true},{"text":"Nada: time travel guarda copias por 90 días","ok":false},{"text":"Borrar la tabla","ok":false},{"text":"Cambiar de región","ok":false}],"enunciado":"<p>¿Qué conviene hacer antes de una carga grande y riesgosa?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true},{"type":"quiz","id":"bigquery-paso-a-paso-proyecto-final-analitica-tienda-andina-ej4","opciones":[{"text":"AZ-900","ok":false},{"text":"Professional Data Engineer","ok":true},{"text":"SnowPro Core","ok":false},{"text":"PL-300","ok":false}],"enunciado":"<p>¿Qué certificación de Google Cloud evalúa diseño, costos y seguridad en BigQuery?</p>\n","dificultad":"6 · Avanzado completo","dificultadLeccion":true}]}});
